    OUTCOME_GROUPS = {
        "stoch14": ("stoch14_k", [(None, 20, "≤ 20 (oversold zone)"), (20, 80, "20–80"), (80, None, "≥ 80 (overbought zone)")]),
        "stoch30": ("stoch30_k", [(None, 20, "≤ 20"), (20, 80, "20–80"), (80, None, "≥ 80")]),
