def _hm(hhmm):
    """'14:30' -> '2:30 PM'."""
    return dt.datetime.strptime(hhmm, "%H:%M").strftime("%-I:%M %p") if hhmm else ""


def _days(a, b):
    d = a
    while d <= b:
        yield d
        d += dt.timedelta(days=1)


