CREATE TABLE prices(symbol TEXT NOT NULL, day TEXT NOT NULL, close REAL NOT NULL, PRIMARY KEY(symbol, day));
CREATE TABLE dividends(run_id INTEGER NOT NULL, ex_day TEXT NOT NULL, amount REAL NOT NULL, PRIMARY KEY(run_id, ex_day));
CREATE TABLE splits(symbol TEXT NOT NULL, day TEXT NOT NULL, ratio REAL NOT NULL, handled INTEGER DEFAULT 0,
  PRIMARY KEY(symbol, day));
CREATE TABLE reports(id INTEGER PRIMARY KEY, ts TEXT NOT NULL, data TEXT NOT NULL);
""",
    2: """
CREATE TABLE trade_readings(event_id INTEGER PRIMARY KEY, asof TEXT NOT NULL, data TEXT NOT NULL);
""",
    3: """
CREATE TABLE earnings(symbol TEXT NOT NULL, day TEXT NOT NULL, PRIMARY KEY(symbol, day));
""",
    4: """
CREATE TABLE iv_history(day TEXT PRIMARY KEY, iv REAL NOT NULL, price REAL, asof TEXT NOT NULL, points TEXT);
""",
    # v1.9.0: account value no longer counts accrued (unpaid) interest; restate past snapshots the same way
    5: """
UPDATE snapshots SET account_value_c = available_c + collateral_c
  + CAST(ROUND(COALESCE(shares, 0) * COALESCE(share_price, 0) * 100) AS INTEGER);
""",
    # v1.12.0: your own notes, events and reminders on the calendar
    6: """
CREATE TABLE notes(id INTEGER PRIMARY KEY, day TEXT NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL,
  body TEXT DEFAULT '', time TEXT, remind TEXT DEFAULT 'none', reminded_at TEXT, created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL, deleted INTEGER DEFAULT 0);
CREATE INDEX notes_day ON notes(day);
""",
}
SCHEMA_VERSION = max(MIGRATIONS)


class DB:
    """Thin thread-safe wrapper. All writes go through `tx()`."""

    def __init__(self, path):
        self.path = str(path)
        self.conn = sqlite3.connect(self.path, check_same_thread=False, isolation_level=None)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute("PRAGMA foreign_keys=ON")
        self.conn.execute("PRAGMA journal_mode=WAL")
        self.lock = threading.RLock()
        self._depth = 0
        self.migrate()

    def version(self):
        try:
            r = self.conn.execute("SELECT value FROM meta WHERE key='schema_version'").fetchone()
            return int(r[0]) if r else 0
        except sqlite3.OperationalError:
            return 0

    def migrate(self):
        with self.lock:
            v = self.version()
            if v > SCHEMA_VERSION:
                raise RuntimeError(
                    f"ledger.db is from a newer Ghost Trader (schema {v}, this app knows {SCHEMA_VERSION})."
                )
            for n in range(v + 1, SCHEMA_VERSION + 1):
                self.conn.execute("BEGIN")
                try:
                    for stmt in _split(MIGRATIONS[n]):
                        self.conn.execute(stmt)
                    self.conn.execute(
                        "INSERT OR REPLACE INTO meta(key,value) VALUES('schema_version',?)", (str(n),))
                    self.conn.execute("COMMIT")
                except Exception:
                    self.conn.execute("ROLLBACK")
                    raise

    # --- helpers -----------------------------------------------------------------------------
    def q(self, sql, args=()):
        with self.lock:
            return self.conn.execute(sql, args).fetchall()

    def one(self, sql, args=()):
        with self.lock:
            return self.conn.execute(sql, args).fetchone()

    def val(self, sql, args=(), default=None):
        r = self.one(sql, args)
        return default if r is None or r[0] is None else r[0]

    def x(self, sql, args=()):
        with self.lock:
            return self.conn.execute(sql, args).lastrowid

    def tx(self):
        return _Tx(self)

    def backup(self, dest):
        with self.lock:
            out = sqlite3.connect(str(dest))
            self.conn.backup(out)
            out.close()

    def close(self):
        with self.lock:
            self.conn.close()


class _Tx:
    def __init__(self, db):
        self.db = db

    def __enter__(self):
        self.db.lock.acquire()
        if self.db._depth == 0:
            self.db.conn.execute("BEGIN IMMEDIATE")
        self.db._depth += 1
        return self.db

    def __exit__(self, et, ev, tb):
        self.db._depth -= 1
        try:
            if self.db._depth == 0:
                self.db.conn.execute("ROLLBACK" if et else "COMMIT")
        finally:
            self.db.lock.release()
        return False


def _split(script):
    return [s.strip() for s in script.split(";") if s.strip()]


def rotate_backups(db, folder, keep=30, label="startup"):
    folder.mkdir(parents=True, exist_ok=True)
    stamp = timeutil.now_ct().strftime("%Y%m%d-%H%M%S")
    dest = folder / f"ledger-{stamp}-{label}.db"
    db.backup(dest)
    files = sorted(folder.glob("ledger-*.db"))
    for old in files[:-keep]:
        old.unlink(missing_ok=True)
    return dest


def inspect_ledger(path, live=False):
    """What a ledger file holds, without opening it as the live ledger. Raises ValueError if it isn't a Ghost
    Trader ledger this version can use."""
    import sqlite3
    try:
        # immutable: a backup or upload is read as-is, without leaving -wal/-shm files beside it
        c = sqlite3.connect(f"file:{path}?mode=ro" + ("" if live else "&immutable=1"), uri=True)
        try:
            names = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if not {"meta", "runs", "events"} <= names:
                raise ValueError("That file isn't a Ghost Trader ledger.")
            r = c.execute("SELECT value FROM meta WHERE key='schema_version'").fetchone()
            v = int(r[0]) if r else 0
            if v > SCHEMA_VERSION:
                raise ValueError(f"That ledger is from a newer Ghost Trader (schema {v}); update the app first.")
            run = c.execute("SELECT start_day, start_cash_c FROM runs WHERE closed_at IS NULL ORDER BY id DESC LIMIT 1").fetchone()
            closed = c.execute("SELECT COUNT(*) FROM runs WHERE closed_at IS NOT NULL").fetchone()[0]
            ev = c.execute("SELECT COUNT(*), MAX(ts) FROM events").fetchone()
            trades = c.execute("SELECT COUNT(*) FROM events WHERE kind='Trade'").fetchone()[0]
            snap = None
            if "snapshots" in names:
                snap = c.execute("SELECT day, account_value_c FROM snapshots ORDER BY day DESC LIMIT 1").fetchone()
        finally:
            c.close()
    except sqlite3.DatabaseError as e:
        raise ValueError(f"That file isn't a Ghost Trader ledger ({e}).") from None
    return {"schema": v, "run_start": run and run[0], "run_cash_c": run and run[1], "closed_runs": closed,
            "events": ev[0], "last_event": ev[1], "trades": trades,
            "last_day": snap and snap[0], "last_value_c": snap and snap[1]}


def restore_backup(src, dest):
    """Copy a backup over the ledger (and drop the write-ahead log files that belonged to the old one)."""
    for suffix in ("-wal", "-shm"):
        p = str(dest) + suffix
        try:
            import os
            os.remove(p)
        except FileNotFoundError:
            pass
    shutil.copy2(src, dest)

ghost_trader/indicators.py:
"""Market indicators for the Indicators tab and the readings stamped on trades.

- Stochastic oscillator on TQQQ daily bars: 14,3,3 (slow: %K smoothed 3, %D = 3-day average of %K) and raw
  %K over 30, 60 and 180 days.
- VIX (CBOE Volatility Index) daily closes.
- CNN Fear & Greed index (no official feed: read from the JSON CNN's own page uses; may break without notice).

Each source is fetched on demand, cached in memory, and fails on its own without affecting the others.
"""
from __future__ import annotations

import datetime as dt
import json
import logging
import threading
import time
import urllib.request

from . import SYMBOL, timeutil

log = logging.getLogger(__name__)

LOOKBACKS = (14, 30, 60, 180)
SLOW = {14: (3, 3)}          # lookback -> (%K smoothing, %D period); others are raw %K
TTL = 15 * 60                 # seconds before a refresh
HISTORY_DAYS = 5 * 365 + 300  # 5 years shown + room for the 180-day lookback
VIX = "^VIX"

CNN_URL = "https://production.dataviz.cnn.io/index/fearandgreed/graphdata/{start}"
CNN_HEADERS = {
    "User-Agent": "Mozilla/5.0 (X11; Linux x86_64; rv:132.0) Gecko/20100101 Firefox/132.0",
    "Accept": "application/json, text/plain, */*",
    "Referer": "https://edition.cnn.com/",
    "Origin": "https://edition.cnn.com",
}


# ---------------------------------------------------------------- math
def sma(vals, n):
    """Simple moving average; None until n values are available (Nones in the window give None)."""
    out = []
    for i in range(len(vals)):
        w = vals[max(0, i - n + 1):i + 1]
        out.append(sum(w) / n if len(w) == n and None not in w else None)
    return out


def raw_k(bars, n):
    """%K = 100 × (close − lowest low) ÷ (highest high − lowest low) over the last n bars."""
    out = []
    for i in range(len(bars)):
        if i + 1 < n:
            out.append(None)
            continue
        w = bars[i + 1 - n:i + 1]
        hh = max(b["high"] for b in w)
        ll = min(b["low"] for b in w)
        out.append(100.0 * (bars[i]["close"] - ll) / (hh - ll) if hh > ll else 50.0)
    return out


def stochastic(bars, n):
    """Returns (k, d): for 14 the slow stochastic (%K smoothed 3, %D 3); for other lookbacks raw %K and d=None."""
    k = raw_k(bars, n)
    if n in SLOW:
        ks, dp = SLOW[n]
        k = sma(k, ks)
        return k, sma(k, dp)
    return k, None


def fg_rating(score):
    """CNN's bands: 0–24 extreme fear, 25–44 fear, 45–55 neutral, 56–75 greed, 76–100 extreme greed."""
    if score is None:
        return None
    s = round(score)
    return ("extreme fear" if s < 25 else "fear" if s < 45 else "neutral" if s <= 55 else "greed" if s <= 75
            else "extreme greed")


def parse_cnn(j):
    """CNN graphdata JSON -> {score, rating, asof, previous_close, week_ago, month_ago, year_ago, history{day: score}}."""
    cur = j.get("fear_and_greed") or {}
    if cur.get("score") is None:
        raise ValueError("no current score in CNN's data")
    hist = {}
    for p in (j.get("fear_and_greed_historical") or {}).get("data") or []:
        try:
            d = dt.datetime.fromtimestamp(float(p["x"]) / 1000, dt.timezone.utc).astimezone(timeutil.ET).date()
            hist[d.isoformat()] = float(p["y"])
        except (KeyError, TypeError, ValueError):
            continue

    def f(k):
        v = cur.get(k)
        return float(v) if isinstance(v, (int, float)) else None

    return {"score": float(cur["score"]), "rating": str(cur.get("rating") or fg_rating(cur["score"])).lower(),
            "asof": cur.get("timestamp"), "previous_close": f("previous_close"), "week_ago": f("previous_1_week"),
            "month_ago": f("previous_1_month"), "year_ago": f("previous_1_year"), "history": hist}


def fetch_cnn(start, timeout=10):
    req = urllib.request.Request(CNN_URL.format(start=start.isoformat()), headers=CNN_HEADERS)
    with urllib.request.urlopen(req, timeout=timeout) as r:  # noqa: S310 - fixed https URL
        return parse_cnn(json.loads(r.read().decode("utf-8")))


# ---------------------------------------------------------------- data + cache
class Indicators:
    def __init__(self, provider):
        self.provider = provider
        self.lock = threading.Lock()
        self.warming = None
        self.data = {}   # source -> {"ok": bool, "value": ..., "error": str, "at": epoch}
        self.on_refresh = None  # called (no args) after a refresh that got new data

    def _fresh(self, src, ttl=TTL):
        e = self.data.get(src)
        return bool(e and e["ok"] and time.time() - e["at"] < ttl)

    def stale(self, ttl=TTL):
        return not all(self._fresh(s, ttl) for s in ("tqqq", "vix", "fg"))

    def refresh(self, force=False):
        """Fetch any source that's stale (or all, with force). Never raises."""
        with self.lock:
            today = timeutil.today_ct()
            start = today - dt.timedelta(days=HISTORY_DAYS)
            jobs = {"tqqq": lambda: self.provider.daily_bars(SYMBOL, start, today),
                    "vix": lambda: self.provider.daily_closes(start, today, symbol=VIX),
                    "fg": lambda: self.provider.fear_greed(today - dt.timedelta(days=5 * 365 + 10))}
            for src, fn in jobs.items():
                if not force and self._fresh(src):
                    continue
                try:
                    v = fn()
                    if not v:
                        raise ValueError("no data returned")
                    self.data[src] = {"ok": True, "value": v, "error": None, "at": time.time()}
                except Exception as e:  # noqa: BLE001
                    log.warning("indicator %s failed: %s", src, e)
                    prev = self.data.get(src) or {}
                    # keep the last good value (marked failed) so the tab still shows something
                    self.data[src] = {"ok": False, "value": prev.get("value"), "error": str(e) or e.__class__.__name__,
                                      "at": prev.get("at", 0)}
            got_new = any(self.data.get(x, {}).get("ok") for x in jobs)
        if got_new and self.on_refresh:
            try:
                self.on_refresh()
            except Exception:  # noqa: BLE001
                log.exception("on_refresh")

    def warm(self):
        """Refresh in the background if stale; returns immediately."""
        if not self.stale() or (self.warming and self.warming.is_alive()):
            return
        self.warming = threading.Thread(target=self.refresh, daemon=True, name="indicators")
        self.warming.start()

    def wait_warm(self, timeout):
        t = self.warming
        if t and t.is_alive():
            t.join(timeout)

    # ------------------------------------------------------------ views
    def _series(self):
        bars = sorted((self.data.get("tqqq") or {}).get("value") or [], key=lambda b: b["day"])
        days = [b["day"] for b in bars]
        stoch = {}
        for n in LOOKBACKS:
            k, d = stochastic(bars, n)
            stoch[str(n)] = {"k": k, "d": d}
        vix_map = (self.data.get("vix") or {}).get("value") or {}
        fg = (self.data.get("fg") or {}).get("value") or {}
        fg_map = fg.get("history") or {}
        if fg.get("score") is not None and days and days[-1] not in fg_map and fg.get("asof"):
            # CNN's history may lag today's reading; place the current score on the latest day it's from
            try:
                fd = timeutil.parse(fg["asof"]).astimezone(timeutil.ET).date().isoformat()
                if fd == days[-1]:
                    fg_map = {**fg_map, fd: fg["score"]}
            except Exception:  # noqa: BLE001
                pass
        return bars, days, stoch, vix_map, fg, fg_map

    def snapshot(self):
        """Current readings for stamping on a trade, or None if nothing is available."""
        bars, days, stoch, vix_map, fg, _ = self._series()
        if not days and not vix_map and fg.get("score") is None:
            return None

        def last(v):
            return round(v[-1], 1) if v and v[-1] is not None else None

        out = {"asof": timeutil.iso(), "bars_through": days[-1] if days else None}
        for n in LOOKBACKS:
            out[f"stoch{n}_k"] = last(stoch[str(n)]["k"])
            if stoch[str(n)]["d"] is not None:
                out[f"stoch{n}_d"] = last(stoch[str(n)]["d"])
        vd = sorted(vix_map)
        out["vix"] = round(vix_map[vd[-1]], 2) if vd else None
        out["fg"] = round(fg["score"], 1) if fg.get("score") is not None else None
        out["fg_rating"] = fg.get("rating")
        return out if any(v is not None for k, v in out.items() if k not in ("asof", "bars_through")) else None

    def view(self, months):
        """Everything the Indicators tab draws, trimmed to the last `months` months."""
        bars, days, stoch, vix_map, fg, fg_map = self._series()
        cut = (timeutil.today_ct() - dt.timedelta(days=int(months * 30.44))).isoformat()
        i0 = next((i for i, d in enumerate(days) if d >= cut), len(days))
        sl = slice(i0, None)
        r = lambda v: [None if x is None else round(x, 2) for x in v]  # noqa: E731
        vd = sorted(vix_map)
        vix_now = vix_map[vd[-1]] if vd else None
        vix_prev = vix_map[vd[-2]] if len(vd) > 1 else None
        yr = [vix_map[d] for d in vd if d >= (timeutil.today_ct() - dt.timedelta(days=365)).isoformat()]
        status = {s: {"ok": (self.data.get(s) or {}).get("ok", False), "error": (self.data.get(s) or {}).get("error"),
                      "at": timeutil.iso(dt.datetime.fromtimestamp(self.data[s]["at"], dt.timezone.utc))
                      if (self.data.get(s) or {}).get("at") else None} for s in ("tqqq", "vix", "fg")}
        cur = {}
        for n in LOOKBACKS:
            k, d = stoch[str(n)]["k"], stoch[str(n)]["d"]
            cur[str(n)] = {"k": k[-1] if k else None, "d": d[-1] if d else None,
                           "k_prev": k[-2] if len(k) > 1 else None}
        return {
            "days": days[sl], "close": [b["close"] for b in bars][sl],
            "stoch": {n: {"k": r(v["k"][sl]), "d": r(v["d"][sl]) if v["d"] is not None else None}
                      for n, v in stoch.items()},
            "vix": [vix_map.get(d) for d in days[sl]], "fg": [fg_map.get(d) for d in days[sl]],
            "now": {"price": bars[-1]["close"] if bars else None, "prev": bars[-2]["close"] if len(bars) > 1 else None,
                    "bars_through": days[-1] if days else None, "stoch": cur,
                    "vix": vix_now, "vix_prev": vix_prev, "vix_hi": max(yr) if yr else None,
                    "vix_lo": min(yr) if yr else None,
                    "fg": {k: v for k, v in fg.items() if k != "history"} if fg else None},
            "status": status, "lookbacks": list(LOOKBACKS), "slow": {str(k): list(v) for k, v in SLOW.items()},
        }

ghost_trader/ledger.py:
"""The paper account: cash journal, positions, share lots, trade rules, expirations, interest, snapshots.

Money is kept in integer cents. Cash lives in two buckets: `available` (spendable) and `collateral`
(securing short puts). Every movement is a row in `cash`, so balances on any past day can be rebuilt.

Account value = available + collateral + shares x current price (v1.9.0: interest counts once it's paid on the 15th;
accrued, unpaid interest is shown separately). Open options' buy-back prices are deliberately excluded.
"""
import datetime as dt
import json
from decimal import ROUND_HALF_UP, Decimal

from . import SYMBOL, marketcal, timeutil
from .timeutil import fmt_date, fmt_exp

SIZING_WARN = 0.80
NEAR_MONEY = 0.03


class TradeError(Exception):
    """A rule refused the trade; the message is shown to the user as-is."""


def cents(x):
    return int(Decimal(str(x)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) * 100)


def money(c, sign=False):
    v = c / 100
    s = f"${abs(v):,.2f}"
    if v < 0:
        return "−" + s
    return ("+" + s) if sign and v > 0 else s


def strike_txt(k):
    return f"${k:g}" if k == int(k) else f"${k:.2f}".rstrip("0")


def label(type_, expiry, strike, symbol=SYMBOL):
    return f"{symbol} {fmt_exp(expiry)} {strike_txt(strike)} {'Put' if type_ == 'put' else 'Call'}"


def plural(n, word):
    return f"{n} {word}{'' if n == 1 else 's'}"


ACTIONS = ("sell_to_open", "buy_to_close", "buy_to_open", "sell_to_close", "buy_shares", "sell_shares")
ACTION_WORDS = {
    "sell_to_open": "Sell to open", "buy_to_close": "Buy to close", "buy_to_open": "Buy to open",
    "sell_to_close": "Sell to close", "buy_shares": "Buy", "sell_shares": "Sell",
}


class Ledger:
    def __init__(self, db, settings):
        self.db = db
        self.settings = settings

    # ------------------------------------------------------------------ runs
    def run(self):
        return self.db.one("SELECT * FROM runs WHERE closed_at IS NULL ORDER BY id DESC LIMIT 1")

    def run_id(self):
        r = self.run()
        return r["id"] if r else None

    def start_run(self, start_cash, ts=None):
        if self.run():
            raise TradeError("A run is already open. Close it first (Settings → Close run).")
        sc = cents(start_cash)
        if sc <= 0:
            raise TradeError("Starting cash must be more than $0.")
        ts = ts or timeutil.now()
        day = ts.astimezone(timeutil.CT).date().isoformat()
        with self.db.tx():
            rid = self.db.x("INSERT INTO runs(started_at,start_day,start_cash_c) VALUES(?,?,?)",
                            (timeutil.iso(ts), day, sc))
            ev = self.event("Run", "New run started", f"Starting cash {money(sc)}.", ts=ts, run_id=rid)
            self.move("available", sc, "starting cash", ts, ev, run_id=rid)
        return rid

    # ------------------------------------------------------------------ events & cash
    def event(self, kind, title, detail="", data=None, tags=(), ts=None, error=False, warning=False,
              position_id=None, lot_id=None, run_id=None):
        rid = run_id if run_id is not None else self.run_id()
        eid = self.db.x(
            "INSERT INTO events(run_id,ts,kind,title,detail,data,is_error,is_warning,position_id,lot_id)"
            " VALUES(?,?,?,?,?,?,?,?,?,?)",
            (rid, timeutil.iso(ts), kind, title, detail, json.dumps(data or {}), int(error), int(warning),
             position_id, lot_id))
        for t in tags or ():
            self.db.x("INSERT OR IGNORE INTO event_tags(event_id,tag) VALUES(?,?)", (eid, t))
        return eid

    def move(self, bucket, amount_c, reason, ts, event_id=None, run_id=None):
        if amount_c == 0:
            return
        rid = run_id if run_id is not None else self.run_id()
        day = ts.astimezone(timeutil.CT).date().isoformat()
        self.db.x("INSERT INTO cash(run_id,ts,day,bucket,amount_c,reason,event_id) VALUES(?,?,?,?,?,?,?)",
                  (rid, timeutil.iso(ts), day, bucket, amount_c, reason, event_id))

    def balances(self, day=None, run_id=None):
        rid = run_id or self.run_id()
        if rid is None:
            return 0, 0
        sql = "SELECT bucket, SUM(amount_c) FROM cash WHERE run_id=?"
        args = [rid]
        if day:
            sql += " AND day<=?"
            args.append(day if isinstance(day, str) else day.isoformat())
        rows = dict(self.db.q(sql + " GROUP BY bucket", args))
        return rows.get("available", 0) or 0, rows.get("collateral", 0) or 0

    def available(self):
        return self.balances()[0]

    # ------------------------------------------------------------------ shares
    def lots(self, open_only=True):
        rid = self.run_id()
        sql = "SELECT * FROM lots WHERE run_id=?" + (" AND open_qty>0" if open_only else "") + " ORDER BY id"
        return self.db.q(sql, (rid,))

    def shares(self):
        return self.db.val("SELECT SUM(open_qty) FROM lots WHERE run_id=?", (self.run_id(),), 0)

    def shares_on(self, day, run_id=None):
        rid = run_id or self.run_id()
        d = day if isinstance(day, str) else day.isoformat()
        r = self.db.one(
            "SELECT SUM(CASE direction WHEN 'in' THEN qty ELSE -qty END) FROM lot_moves WHERE run_id=? AND day<=?",
            (rid, d))
        return r[0] or 0

    def locked_shares(self):
        return 100 * self.db.val(
            "SELECT SUM(open_qty) FROM positions WHERE run_id=? AND status='open' AND type='call' AND side='short'",
            (self.run_id(),), 0)

    def free_shares(self):
        return self.shares() - self.locked_shares()

    def avg_cost(self):
        rows = self.lots()
        n = sum(r["open_qty"] for r in rows)
        return sum(r["open_qty"] * r["cost"] for r in rows) / n if n else 0.0

    def _add_lot(self, qty, price, ts, source, how, event_id, position_id=None):
        day = ts.astimezone(timeutil.CT).date().isoformat()
        lid = self.db.x(
            "INSERT INTO lots(run_id,symbol,qty,open_qty,cost,acquired_at,acquired_day,source,source_position_id)"
            " VALUES(?,?,?,?,?,?,?,?,?)",
            (self.run_id(), SYMBOL, qty, qty, price, timeutil.iso(ts), day, source, position_id))
        self.db.x("INSERT INTO lot_moves(run_id,lot_id,ts,day,direction,qty,price,how,event_id,position_id)"
                  " VALUES(?,?,?,?,'in',?,?,?,?,?)",
                  (self.run_id(), lid, timeutil.iso(ts), day, qty, price, how, event_id, position_id))
        return lid

    def _remove_shares(self, qty, price, ts, how, event_id, prefer_lot=None, position_id=None):
        """Take `qty` shares out of lots (preferred lot first, then oldest first). Returns [(lot_id, n, cost)]."""
        day = ts.astimezone(timeutil.CT).date().isoformat()
        lots = list(self.lots())
        if prefer_lot:
            lots.sort(key=lambda r: (r["id"] != prefer_lot, r["id"]))
        taken, left = [], qty
        for lot in lots:
            if left <= 0:
                break
            n = min(left, lot["open_qty"])
            self.db.x("UPDATE lots SET open_qty=open_qty-?, closed_at=CASE WHEN open_qty-?=0 THEN ? END WHERE id=?",
                      (n, n, timeutil.iso(ts), lot["id"]))
            self.db.x("INSERT INTO lot_moves(run_id,lot_id,ts,day,direction,qty,price,how,event_id,position_id)"
                      " VALUES(?,?,?,?,'out',?,?,?,?,?)",
                      (self.run_id(), lot["id"], timeutil.iso(ts), day, n, price, how, event_id, position_id))
            taken.append((lot["id"], n, lot["cost"]))
            left -= n
        if left > 0:
            raise TradeError(f"Not enough shares: needed {qty}, found {qty - left}.")
        return taken

    # ------------------------------------------------------------------ positions
    def positions(self, open_only=True):
        rid = self.run_id()
        sql = "SELECT * FROM positions WHERE run_id=?" + (" AND status='open'" if open_only else "")
        return [self._pos(r) for r in self.db.q(sql + " ORDER BY expiry, strike", (rid,))]

    def position(self, pid):
        r = self.db.one("SELECT * FROM positions WHERE id=?", (pid,))
        return self._pos(r) if r else None

    def _pos(self, r):
        d = dict(r)
        d["tags"] = [t[0] for t in self.db.q("SELECT tag FROM position_tags WHERE position_id=? ORDER BY tag", (r["id"],))]
        d["label"] = label(r["type"], r["expiry"], r["strike"], r["symbol"])
        return d

    def _set_tags(self, pid, tags):
        for t in tags:
            self.db.x("INSERT OR IGNORE INTO position_tags(position_id,tag) VALUES(?,?)", (pid, t))

    # ------------------------------------------------------------------ valuation
    def accrued(self, run_id=None, as_of=None):
        rid = run_id or self.run_id()
        if as_of is None:
            return self.db.val("SELECT SUM(amount) FROM accruals WHERE run_id=? AND paid_day IS NULL", (rid,), 0.0)
        d = as_of.isoformat() if not isinstance(as_of, str) else as_of
        return self.db.val(
            "SELECT SUM(amount) FROM accruals WHERE run_id=? AND day<=? AND (paid_day IS NULL OR paid_day>?)",
            (rid, d, d), 0.0)

    def account_value_c(self, share_price):
        a, c = self.balances()
        return a + c + cents(self.shares() * (share_price or 0))

    def breakdown(self, share_price):
        a, c = self.balances()
        acc = self.accrued()
        sh = self.shares()
        return {
            "available_c": a, "collateral_c": c, "accrued": round(acc, 6), "accrued_c": cents(acc),
            "shares": sh, "share_price": share_price, "shares_value_c": cents(sh * (share_price or 0)),
            "account_value_c": a + c + cents(sh * (share_price or 0)),
        }

    # ------------------------------------------------------------------ order checking
    def check(self, order, quote, share_price, ts=None):
        """Validate an order against the rules and the current quote. Returns a dict with ok/msg/effects.
        Never raises for rule failures; `place()` raises TradeError with the same message."""
        o = _norm(order)
        res = {"ok": False, "msg": "", "warn": None, "effects": {}, "order": o}
        if not self.run():
            res["msg"] = "Start a run first (enter your starting cash)."
            return res
        act = o["action"]
        if act not in ACTIONS:
            res["msg"] = "Unknown action."
            return res
        qty = o["qty"]
        if not isinstance(qty, int) or qty <= 0:
            res["msg"] = "Enter how many shares." if act.endswith("shares") else "Enter how many contracts."
            return res
        px = o["price"]
        bid, ask = (quote or {}).get("bid"), (quote or {}).get("ask")
        if quote is None or ask is None or (not ask and not bid):
            res["msg"] = "No usable quote for this contract right now, so it can't be traded until one is available."
            return res
        bid = bid or 0.0
        if px is None:
            res["msg"] = "Enter a fill price."
            return res
        pc, bc, ac = cents(px), cents(bid), cents(ask)
        if pc > ac:
            res["msg"] = f"{px:.2f} is above the ask. Enter a price from {bid:.2f} to {ask:.2f}."
            return res
        if pc < bc:
            res["msg"] = f"{px:.2f} is below the bid. Enter a price from {bid:.2f} to {ask:.2f}."
            return res
        if pc <= 0 and act in ("sell_to_open", "sell_shares", "sell_to_close", "buy_shares"):
            res["msg"] = "The fill price has to be more than 0.00."
            return res
        avail, coll = self.balances()
        mult = 1 if act.endswith("shares") else 100
        gross = pc * qty * mult
        eff = {"gross_c": gross, "available_before_c": avail}
        msg = ""
        if act == "sell_to_open":
            if o["type"] == "put":
                need = cents(o["strike"]) * 100 * qty
                if need > avail:
                    res["msg"] = (f"Not cash-secured: needs {money(need)}, you have {money(avail)} available. "
                                  "Collateral must come from cash you already have, not this trade's premium.")
                    return res
                eff.update(premium_c=gross, collateral_c=need, available_after_c=avail - need + gross)
                msg = f"Cash-secured: {money(avail)} available ≥ {money(need)} required"
                av = self.account_value_c(share_price)
                if av and need / av > SIZING_WARN:
                    res["warn"] = (f"This trade's collateral ({money(need)}) is {need / av * 100:.1f}% of account value "
                                   f"(warning above {SIZING_WARN * 100:.0f}%). You can still confirm.")
            else:
                free = self.free_shares()
                if free < qty * 100:
                    sh, lk = self.shares(), self.locked_shares()
                    res["msg"] = (f"Not covered: you hold {sh} shares, {lk} already covering, {max(free, 0)} free. "
                                  f"Need {qty * 100}.")
                    return res
                eff.update(premium_c=gross, locks_shares=qty * 100, available_after_c=avail + gross)
                msg = f"Covered: {free} free shares ≥ {qty * 100} needed"
        elif act == "buy_to_open":
            if not self.settings.get("long_options"):
                res["msg"] = "Buying options to open is off (Settings → Trading)."
                return res
            if gross > avail:
                res["msg"] = f"Not enough cash: costs {money(gross)}, you have {money(avail)} available."
                return res
            eff.update(cost_c=gross, available_after_c=avail - gross)
            msg = f"Paid from Available: {money(gross)}"
        elif act in ("buy_to_close", "sell_to_close"):
            p = self.position(o["position_id"]) if o.get("position_id") else None
            if not p or p["status"] != "open" or p["run_id"] != self.run_id():
                res["msg"] = "That position isn't open."
                return res
            if qty > p["open_qty"]:
                res["msg"] = f"You only have {plural(p['open_qty'], 'contract')} open."
                return res
            want_side = "short" if act == "buy_to_close" else "long"
            if p["side"] != want_side:
                res["msg"] = "That action doesn't match the position."
                return res
            if act == "buy_to_close":
                if p["type"] == "put":
                    released = p["collateral_c"] * qty // p["open_qty"]
                    if gross > released + avail:
                        res["msg"] = f"Not enough cash: buying back costs {money(gross)}."
                        return res
                    eff.update(cost_c=gross, collateral_released_c=released,
                               available_after_c=avail + released - gross)
                else:
                    if gross > avail:
                        res["msg"] = f"Not enough cash: buying back costs {money(gross)}, you have {money(avail)} available."
                        return res
                    eff.update(cost_c=gross, unlocks_shares=qty * 100, available_after_c=avail - gross)
                eff["result_c"] = cents(p["open_price"]) * 100 * qty - gross
                msg = f"Closes {plural(qty, 'contract')} of {p['label']}."
            else:
                eff.update(proceeds_c=gross, available_after_c=avail + gross,
                           result_c=gross - cents(p["open_price"]) * 100 * qty)
                msg = f"Closes {plural(qty, 'contract')} of {p['label']}."
        elif act == "buy_shares":
            if gross > avail:
                res["msg"] = f"Not enough cash: costs {money(gross)}, you have {money(avail)} available."
                return res
            eff.update(cost_c=gross, available_after_c=avail - gross)
            msg = f"Paid from Available: {money(gross)}"
        elif act == "sell_shares":
            free = self.free_shares()
            if qty > free:
                res["msg"] = (f"Only {free} shares are free to sell ({self.locked_shares()} are covering calls). "
                              "Close or let the calls expire first.")
                return res
            eff.update(proceeds_c=gross, available_after_c=avail + gross)
            msg = f"{free} free shares ≥ {qty}"
        res.update(ok=True, msg=msg, effects=eff)
        return res

    # ------------------------------------------------------------------ placing
    def place(self, order, quote, share_price, ts=None):
        ts = ts or timeutil.now()
        chk = self.check(order, quote, share_price, ts)
        if not chk["ok"]:
            raise TradeError(chk["msg"])
        o = chk["order"]
        act, qty, px = o["action"], o["qty"], o["price"]
        pc = cents(px)
        tags = o["tags"]
        with self.db.tx():
            if act == "sell_to_open":
                return self._sell_to_open(o, qty, px, pc, tags, ts)
            if act == "buy_to_open":
                return self._buy_to_open(o, qty, px, pc, tags, ts)
            if act in ("buy_to_close", "sell_to_close"):
                return self._close(o, qty, px, pc, ts)
            if act == "buy_shares":
                return self._buy_shares(o, qty, px, pc, tags, ts)
            return self._sell_shares(o, qty, px, pc, tags, ts)

    def _sell_to_open(self, o, qty, px, pc, tags, ts):
        typ, k, exp = o["type"], o["strike"], o["expiry"]
        prem = pc * 100 * qty
        lab = label(typ, exp, k)
        coll = cents(k) * 100 * qty if typ == "put" else 0
        lot_id = None
        if typ == "call":
            # Attach the call to the oldest lot that still has uncovered shares (for the lot story).
            covered = {}
            for r in self.db.q("SELECT lot_id, SUM(open_qty) n FROM positions WHERE run_id=? AND status='open' "
                               "AND type='call' AND side='short' GROUP BY lot_id", (self.run_id(),)):
                covered[r["lot_id"]] = r["n"] * 100
            for lot in self.lots():
                if lot["open_qty"] - covered.get(lot["id"], 0) > 0:
                    lot_id = lot["id"]
                    break
        pid = self.db.x(
            "INSERT INTO positions(run_id,symbol,type,side,expiry,strike,qty,open_qty,open_price,opened_at,"
            "collateral_c,note,lot_id,realized_c) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (self.run_id(), SYMBOL, typ, "short", exp, k, qty, qty, px, timeutil.iso(ts), coll, o["note"], lot_id, prem))
        self._set_tags(pid, tags)
        detail = f"{money(prem, True)} premium" + (f" · {money(coll)} collateral" if coll else
                                                    f" · {qty * 100} shares now covering")
        if o["note"]:
            detail += f" · “{o['note']}”"
        ev = self.event("Trade", f"Sell to open {qty} × {lab} @ {px:.2f}", detail,
                        {"action": "sell_to_open", "qty": qty, "price": px, "premium_c": prem, "collateral_c": coll},
                        tags, ts, position_id=pid, lot_id=lot_id)
        if coll:
            self.move("available", -coll, "collateral set aside", ts, ev)
            self.move("collateral", coll, "collateral set aside", ts, ev)
        self.move("available", prem, "premium", ts, ev)
        return {"event_id": ev, "position_id": pid}

    def _buy_to_open(self, o, qty, px, pc, tags, ts):
        typ, k, exp = o["type"], o["strike"], o["expiry"]
        cost = pc * 100 * qty
        lab = label(typ, exp, k)
        pid = self.db.x(
            "INSERT INTO positions(run_id,symbol,type,side,expiry,strike,qty,open_qty,open_price,opened_at,note,realized_c)"
            " VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
            (self.run_id(), SYMBOL, typ, "long", exp, k, qty, qty, px, timeutil.iso(ts), o["note"], -cost))
        self._set_tags(pid, tags)
        ev = self.event("Trade", f"Buy to open {qty} × {lab} @ {px:.2f}",
                        f"{money(-cost)} cost" + (f" · “{o['note']}”" if o["note"] else ""),
                        {"action": "buy_to_open", "qty": qty, "price": px, "cost_c": cost}, tags, ts, position_id=pid)
        self.move("available", -cost, "option purchase", ts, ev)
        return {"event_id": ev, "position_id": pid}

    def _close(self, o, qty, px, pc, ts):
        p = self.position(o["position_id"])
        gross = pc * 100 * qty
        why = o.get("close_note") or ""
        left = p["open_qty"] - qty
        if p["side"] == "short":
            released = p["collateral_c"] * qty // p["open_qty"] if p["type"] == "put" else 0
            result = cents(p["open_price"]) * 100 * qty - gross
            title = f"Buy to close {qty} × {p['label']} @ {px:.2f}"
            detail = f"{money(-gross)}"
            if released:
                detail += f" from collateral · {money(released - gross)} released to Available"
            detail += f" · result {money(result, True)}"
        else:
            released = 0
            result = gross - cents(p["open_price"]) * 100 * qty
            title = f"Sell to close {qty} × {p['label']} @ {px:.2f}"
            detail = f"{money(gross, True)} · result {money(result, True)}"
        if why:
            detail += f" · “{why}”"
        ev = self.event("Trade", title, detail,
                        {"action": o["action"], "qty": qty, "price": px, "result_c": result, "close_note": why},
                        p["tags"], ts, position_id=p["id"], lot_id=p["lot_id"])
        if p["side"] == "short":
            if released:
                self.move("collateral", -released, "collateral released", ts, ev)
                self.move("available", released, "collateral released", ts, ev)
            self.move("available", -gross, "buy to close", ts, ev)
            realized = p["realized_c"] - gross
        else:
            self.move("available", gross, "sell to close", ts, ev)
            realized = p["realized_c"] + gross
        self.db.x("UPDATE positions SET open_qty=?, collateral_c=collateral_c-?, realized_c=?, status=?, closed_at=? WHERE id=?",
                  (left, released, realized, "open" if left else "closed", None if left else timeutil.iso(ts), p["id"]))
        if not left:
            self._position_summary(p["id"], ts)
        return {"event_id": ev, "position_id": p["id"]}

    def _position_summary(self, pid, ts):
        p = self.position(pid)
        intr = self.interest_on_collateral(p)
        txt = f"Net {money(p['realized_c'], True)} on the option"
        if p["type"] == "put" and p["side"] == "short":
            txt += f" + {money(cents(intr))} est. interest on its collateral"
        self.event("Summary", f"Position closed: {p['label']}", txt + ".",
                   {"realized_c": p["realized_c"], "interest": intr}, p["tags"], ts, position_id=pid, lot_id=p["lot_id"])

    def _buy_shares(self, o, qty, px, pc, tags, ts):
        cost = pc * qty
        ev = self.event("Shares", f"Bought {qty} {SYMBOL} @ {px:.2f}", f"{money(-cost)} from Available"
                        + (f" · “{o['note']}”" if o["note"] else ""),
                        {"action": "buy_shares", "qty": qty, "price": px}, tags, ts)
        self.move("available", -cost, "share purchase", ts, ev)
        lid = self._add_lot(qty, px, ts, "bought", "bought", ev)
        self.db.x("UPDATE events SET lot_id=? WHERE id=?", (lid, ev))
        return {"event_id": ev, "lot_id": lid}

    def _sell_shares(self, o, qty, px, pc, tags, ts):
        proceeds = pc * qty
        ev = self.event("Shares", f"Sold {qty} {SYMBOL} @ {px:.2f}", "", {"action": "sell_shares", "qty": qty, "price": px},
                        tags, ts)
        # Sell from lots that aren't covering calls first.
        covering = {r[0] for r in self.db.q("SELECT lot_id FROM positions WHERE run_id=? AND status='open' AND type='call'"
                                            " AND side='short'", (self.run_id(),))}
        free_first = next((lot["id"] for lot in self.lots() if lot["id"] not in covering), None)
        taken = self._remove_shares(qty, px, ts, "sold", ev, prefer_lot=free_first)
        gain = sum(cents((px - cost) * n) for _, n, cost in taken)
        self.move("available", proceeds, "share sale", ts, ev)
        self.db.x("UPDATE events SET detail=?, lot_id=? WHERE id=?",
                  (f"{money(proceeds, True)} to Available · gain/loss vs. cost {money(gain, True)}"
                   + (f" · “{o['note']}”" if o["note"] else ""), taken[0][0], ev))
        return {"event_id": ev}

    # ------------------------------------------------------------------ expirations
    def due_expirations(self, ts):
        rows = self.db.q("SELECT DISTINCT expiry FROM positions WHERE run_id=? AND status='open' ORDER BY expiry",
                         (self.run_id(),))
        return [dt.date.fromisoformat(r[0]) for r in rows
                if marketcal.expiration_settle_ready(dt.date.fromisoformat(r[0]), ts)]

    def settle_expiration(self, expiry, close, ts=None):
        """Settle every open position expiring on `expiry` against the official close. Auto-exercise / assign
        at >= $0.01 in the money. Returns a list of event ids."""
        ts = ts or timeutil.now()
        exp = expiry.isoformat() if not isinstance(expiry, str) else expiry
        out = []
        with self.db.tx():
            rows = self.db.q("SELECT id FROM positions WHERE run_id=? AND status='open' AND expiry=? "
                             "ORDER BY CASE WHEN type='put' AND side='short' THEN 0 ELSE 1 END, strike",
                             (self.run_id(), exp))
            for r in rows:
                out.append(self._settle_one(self.position(r[0]), close, ts))
        return out

    def _settle_one(self, p, close, ts):
        k, n = p["strike"], p["open_qty"]
        itm = (k - close) if p["type"] == "put" else (close - k)
        itm = round(itm, 4) >= 0.01
        lab = p["label"]
        closetxt = f"{SYMBOL} closed {close:.2f}."
        tags = p["tags"]
        if p["side"] == "short" and p["type"] == "put":
            coll = p["collateral_c"]
            if itm:
                ev = self.event("Assigned", f"Put assigned: bought {n * 100} {SYMBOL} @ {k:.2f}",
                                f"{lab}. {closetxt} {money(coll)} collateral used. Premium kept {money(p['realized_c'], True)}.",
                                {"close": close}, tags, ts, position_id=p["id"])
                self.move("collateral", -coll, "assignment", ts, ev)
                lid = self._add_lot(n * 100, k, ts, "assigned", "assigned", ev, p["id"])
                self.db.x("UPDATE events SET lot_id=? WHERE id=?", (lid, ev))
                self.db.x("UPDATE positions SET lot_id=? WHERE id=?", (lid, p["id"]))
                status = "assigned"
            else:
                ev = self.event("Expired", "Expired worthless",
                                f"{lab} ({n}). {closetxt} {money(coll)} collateral released. "
                                f"Kept {money(p['realized_c'], True)} premium.", {"close": close}, tags, ts, position_id=p["id"])
                self.move("collateral", -coll, "collateral released", ts, ev)
                self.move("available", coll, "collateral released", ts, ev)
                status = "expired"
        elif p["side"] == "short":  # covered call
            if itm:
                proceeds = cents(k) * 100 * n
                ev = self.event("Called away", f"Shares called away: sold {n * 100} {SYMBOL} @ {k:.2f}",
                                f"{lab}. {closetxt} {money(proceeds, True)} to Available. Premium kept "
                                f"{money(p['realized_c'], True)}.", {"close": close}, tags, ts, position_id=p["id"],
                                lot_id=p["lot_id"])
                taken = self._remove_shares(n * 100, k, ts, "called away", ev, prefer_lot=p["lot_id"], position_id=p["id"])
                self.move("available", proceeds, "called away", ts, ev)
                gain = sum(cents((k - cost) * q) for _, q, cost in taken)
                self.db.x("UPDATE events SET detail=detail || ? WHERE id=?",
                          (f" Shares vs. cost {money(gain, True)}.", ev))
                status = "called"
            else:
                ev = self.event("Expired", "Expired worthless",
                                f"{lab} ({n}). {closetxt} {n * 100} shares unlocked. Kept {money(p['realized_c'], True)} premium.",
                                {"close": close}, tags, ts, position_id=p["id"], lot_id=p["lot_id"])
                status = "expired"
        else:  # long option
            if itm and p["type"] == "call":
                cost = cents(k) * 100 * n
                if self.available() >= cost:
                    ev = self.event("Exercised", f"Call exercised: bought {n * 100} {SYMBOL} @ {k:.2f}",
                                    f"{lab}. {closetxt} {money(-cost)} from Available.", {"close": close}, tags, ts,
                                    position_id=p["id"])
                    self.move("available", -cost, "exercise", ts, ev)
                    self._add_lot(n * 100, k, ts, "exercised", "exercised", ev, p["id"])
                else:
                    val = cents((close - k) * 100 * n)
                    ev = self.event("Exercised", f"Long call settled for value {money(val, True)}",
                                    f"{lab}. {closetxt} Not enough cash to take the shares, so it was settled at "
                                    f"intrinsic value.", {"close": close}, tags, ts, position_id=p["id"])
                    self.move("available", val, "cash settlement", ts, ev)
                status = "exercised"
            elif itm:
                if self.free_shares() >= n * 100:
                    proceeds = cents(k) * 100 * n
                    ev = self.event("Exercised", f"Put exercised: sold {n * 100} {SYMBOL} @ {k:.2f}",
                                    f"{lab}. {closetxt} {money(proceeds, True)} to Available.", {"close": close},
                                    tags, ts, position_id=p["id"])
                    self._remove_shares(n * 100, k, ts, "exercised", ev, position_id=p["id"])
                    self.move("available", proceeds, "exercise", ts, ev)
                else:
                    val = cents((k - close) * 100 * n)
                    ev = self.event("Exercised", f"Long put settled for value {money(val, True)}",
                                    f"{lab}. {closetxt} Not enough free shares to deliver, so it was settled at "
                                    f"intrinsic value.", {"close": close}, tags, ts, position_id=p["id"])
                    self.move("available", val, "cash settlement", ts, ev)
                status = "exercised"
            else:
                ev = self.event("Expired", "Expired worthless", f"{lab} ({n}), bought option. {closetxt}",
                                {"close": close}, tags, ts, position_id=p["id"])
                status = "expired"
        self.db.x("UPDATE positions SET status=?, open_qty=0, collateral_c=0, closed_at=? WHERE id=?",
                  (status, timeutil.iso(ts), p["id"]))
        self._position_summary(p["id"], ts)
        return ev

    # ------------------------------------------------------------------ interest
    def last_accrual_day(self, run_id=None):
        rid = run_id or self.run_id()
        d = self.db.val("SELECT MAX(day) FROM accruals WHERE run_id=?", (rid,))
        return dt.date.fromisoformat(d) if d else None

    def accrue_interest(self, through, rate_for_day, haircut=0.0, ts=None):
        """Accrue simple daily interest (actual/365) on all cash for each calendar day from the day after the last
        accrual (or the run start) through `through`, inclusive. `rate_for_day(date)` returns an annual % rate.
        Returns (days, amount)."""
        r = self.run()
        if not r:
            return 0, 0.0
        start = self.last_accrual_day()
        day = (start + dt.timedelta(days=1)) if start else dt.date.fromisoformat(r["start_day"])
        n, total = 0, 0.0
        with self.db.tx():
            while day <= through:
                rate = max(0.0, (rate_for_day(day) or 0.0) - (haircut or 0.0))
                a, c = self.balances(day)
                amt = (a + c) / 100 * rate / 100 / 365
                self.db.x("INSERT OR REPLACE INTO accruals(run_id,day,rate,balance_c,amount) VALUES(?,?,?,?,?)",
                          (r["id"], day.isoformat(), rate, a + c, amt))
                n += 1
                total += amt
                day += dt.timedelta(days=1)
        return n, total

    def pay_interest(self, today, ts=None, force=False):
        """Post unpaid accruals on each pay date (the 15th or the business day before) that has arrived.
        Accruals for days before the pay date are paid. With force=True everything unpaid is paid now (Close run)."""
        r = self.run()
        if not r:
            return []
        ts = ts or timeutil.now()
        paid = []
        first = self.db.val("SELECT MIN(day) FROM accruals WHERE run_id=? AND paid_day IS NULL", (r["id"],))
        if not first:
            return []
        start = dt.date.fromisoformat(first)
        dates = marketcal.pay_dates_between(start, today)
        if force:
            dates = dates + [today]
        with self.db.tx():
            for p in dates:
                rows = self.db.q("SELECT day, amount, rate FROM accruals WHERE run_id=? AND paid_day IS NULL AND "
                                 + ("day<=?" if force and p == today else "day<?"), (r["id"], p.isoformat()))
                if not rows:
                    continue
                amt = sum(x["amount"] for x in rows)
                c = cents(amt)
                d0, d1 = rows[0]["day"], rows[-1]["day"]
                avg = sum(x["rate"] for x in rows) / len(rows)
                pts = ts if (force and p == today) else dt.datetime.combine(p, dt.time(8, 30), timeutil.CT)
                ev = self.event("Interest", f"Interest posted {money(c, True)}",
                                f"{fmt_date(d0)}–{fmt_date(d1)} · avg rate {avg:.2f}% on all cash.",
                                {"amount": amt, "from": d0, "to": d1}, ts=pts)
                self.move("available", c, "interest", pts, ev)
                self.db.x("UPDATE accruals SET paid_day=?, paid_event_id=? WHERE run_id=? AND paid_day IS NULL AND day IN (%s)"
                          % ",".join("?" * len(rows)), [p.isoformat(), ev, r["id"]] + [x["day"] for x in rows])
                paid.append(ev)
        return paid

    def catch_up_interest(self, today, rate_for_day, haircut=0.0, ts=None):
        """Accrue every day before `today` and post each pay date in order, so posted interest earns interest
        from the day it was paid. Returns (days accrued, amount accrued, [interest event ids])."""
        r = self.run()
        if not r:
            return 0, 0.0, []
        last = self.last_accrual_day() or (dt.date.fromisoformat(r["start_day"]) - dt.timedelta(days=1))
        days, amt, evs = 0, 0.0, []
        for p in marketcal.pay_dates_between(last, today):
            n, a = self.accrue_interest(p - dt.timedelta(days=1), rate_for_day, haircut, ts)
            days, amt = days + n, amt + a
            evs += self.pay_interest(p, ts)
        n, a = self.accrue_interest(today - dt.timedelta(days=1), rate_for_day, haircut, ts)
        evs += self.pay_interest(today, ts)
        return days + n, amt + a, evs

    def interest_earned_c(self):
        return self.db.val("SELECT SUM(amount_c) FROM cash WHERE run_id=? AND reason='interest'", (self.run_id(),), 0)

    def interest_on_collateral(self, p):
        """Estimated interest earned on a short put's collateral over the days it was held."""
        if not (p["type"] == "put" and p["side"] == "short"):
            return 0.0
        start = timeutil.parse(p["opened_at"]).astimezone(timeutil.CT).date()
        end = timeutil.parse(p["closed_at"]).astimezone(timeutil.CT).date() if p["closed_at"] else timeutil.today_ct()
        coll = cents(p["strike"]) * 100 * p["qty"] / 100
        rates = [r[0] for r in self.db.q("SELECT rate FROM accruals WHERE run_id=? AND day>=? AND day<? ORDER BY day",
                                         (p["run_id"], start.isoformat(), end.isoformat()))]
        days = max((end - start).days, 0)
        if len(rates) < days:
            last = rates[-1] if rates else self.db.val(
                "SELECT rate FROM accruals WHERE run_id=? ORDER BY day DESC LIMIT 1", (p["run_id"],), 0.0)
            rates += [last] * (days - len(rates))
        return sum(coll * r / 100 / 365 for r in rates[:days])

    # ------------------------------------------------------------------ dividends
    def credit_dividend(self, ex_day, amount, ts=None):
        """Credit a cash dividend for shares held at the close before the ex-date. Idempotent."""
        ts = ts or timeutil.now()
        exd = ex_day if isinstance(ex_day, dt.date) else dt.date.fromisoformat(ex_day)
        r = self.run()
        if not r or exd <= dt.date.fromisoformat(r["start_day"]):
            return None
        if self.db.one("SELECT 1 FROM dividends WHERE run_id=? AND ex_day=?", (r["id"], exd.isoformat())):
            return None
        held = self.shares_on(exd - dt.timedelta(days=1))
        with self.db.tx():
            self.db.x("INSERT INTO dividends(run_id,ex_day,amount) VALUES(?,?,?)", (r["id"], exd.isoformat(), amount))
            if held <= 0:
                return None
            c = cents(amount * held)
            ev = self.event("Dividend", f"Dividend {money(c, True)}",
                            f"{SYMBOL} ex-date {fmt_date(exd)} · ${amount:.4f}/share × {held} shares.",
                            {"amount": amount, "shares": held}, ts=ts)
            self.move("available", c, "dividend", ts, ev)
            return ev

    # ------------------------------------------------------------------ totals
    def premium_collected_c(self):
        return self.db.val("SELECT SUM(amount_c) FROM cash WHERE run_id=? AND reason='premium'", (self.run_id(),), 0)

    def dividends_c(self):
        return self.db.val("SELECT SUM(amount_c) FROM cash WHERE run_id=? AND reason='dividend'", (self.run_id(),), 0)

    # ------------------------------------------------------------------ snapshots
    def snapshot(self, day, share_price, tqqq_close, marks=None, estimated=False, ts=None):
        r = self.run()
        if not r:
            return
        d = day.isoformat() if not isinstance(day, str) else day
        if estimated:
            a, c = self.balances(d)
            acc = self.accrued(as_of=d)
            sh = self.shares_on(d)
        else:
            a, c = self.balances()
            acc = self.accrued()
            sh = self.shares()
        av = a + c + cents(sh * (share_price or 0))
        self.db.x("INSERT OR REPLACE INTO snapshots(run_id,day,ts,available_c,collateral_c,accrued,shares,share_price,"
                  "account_value_c,tqqq_close,marks,estimated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                  (r["id"], d, timeutil.iso(ts), a, c, acc, sh, share_price, av, tqqq_close,
                   json.dumps(marks or {}), int(estimated)))
        return av

    def fill_snapshot_gaps(self, closes, through):
        """Fill trading days without a snapshot (app not opened) using daily closes: {date_iso: close}."""
        r = self.run()
        if not r:
            return 0
        have = {x[0] for x in self.db.q("SELECT day FROM snapshots WHERE run_id=?", (r["id"],))}
        d = dt.date.fromisoformat(r["start_day"])
        n = 0
        while d < through:
            iso = d.isoformat()
            if marketcal.is_trading_day(d) and iso not in have and iso in closes:
                self.snapshot(d, closes[iso], closes[iso], estimated=True)
                n += 1
            d += dt.timedelta(days=1)
        return n


def _norm(order):
    o = dict(order or {})
    o["action"] = o.get("action", "")
    try:
        o["qty"] = int(str(o.get("qty", "")).strip())
    except ValueError:
        o["qty"] = None
    try:
        p = o.get("price")
        o["price"] = None if p in (None, "") else float(str(p).replace("$", "").strip())
    except ValueError:
        o["price"] = None
    if o.get("strike") is not None:
        o["strike"] = float(o["strike"])
    if o.get("position_id") is not None:
        o["position_id"] = int(o["position_id"])
    o["note"] = (o.get("note") or "").strip()
    o["close_note"] = (o.get("close_note") or "").strip()
    tags = []
    for t in o.get("tags") or []:
        t = "#" + str(t).strip().lstrip("#").replace(" ", "-").lower()
        if len(t) > 1 and t not in tags:
            tags.append(t)
    o["tags"] = tags
    return o

ghost_trader/market.py:
"""Market data: option chains, the underlying price, daily closes, dividends/splits (Yahoo via yfinance, ~15 min
delayed), and the interest rate (Alpha Vantage 3-month Treasury -> ^IRX via Yahoo -> manual).

A DemoProvider produces synthetic but consistent data with no network, for `--demo` and the tests.
"""
import datetime as dt
import json
import logging
import math
import random
import threading
import time
import urllib.parse
import urllib.request

from . import SYMBOL, marketcal, timeutil

log = logging.getLogger("ghost_trader.market")


class DataError(Exception):
    pass


# ---------------------------------------------------------------- pricing helpers
def ncdf(x):
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))


def bs(S, K, T, r, sigma, call):
    if T <= 0 or sigma <= 0 or S <= 0:
        return (max(0.0, S - K) if call else max(0.0, K - S)), (1.0 if (call and S > K) else (-1.0 if (not call and S < K) else 0.0))
    d1 = (math.log(S / K) + (r + 0.5 * sigma * sigma) * T) / (sigma * math.sqrt(T))
    d2 = d1 - sigma * math.sqrt(T)
    if call:
        return S * ncdf(d1) - K * math.exp(-r * T) * ncdf(d2), ncdf(d1)
    return K * math.exp(-r * T) * ncdf(-d2) - S * ncdf(-d1), ncdf(d1) - 1.0


IV_MIN, IV_MAX = 0.05, 5.0  # outside this range Yahoo's impliedVolatility is junk, not a real reading


def iv_ok(iv):
    return iv is not None and IV_MIN <= iv <= IV_MAX


def implied_vol(price, S, K, T, r, call):
    """Volatility that makes Black-Scholes match `price` (bisection). None when the price can't be explained
    by any sensible volatility (below intrinsic value, or no time/price to work with)."""
    if not (price and price > 0 and S and S > 0 and K and T and T > 0):
        return None
    lo, hi = 0.01, IV_MAX * 2
    if price <= bs(S, K, T, r, lo, call)[0] or price >= bs(S, K, T, r, hi, call)[0]:
        return None
    for _ in range(80):
        m = (lo + hi) / 2
        if bs(S, K, T, r, m, call)[0] < price:
            lo = m
        else:
            hi = m
    return round((lo + hi) / 2, 4)


def fix_ivs(rows, S, T, r):
    """Yahoo's impliedVolatility is often junk on far out-of-the-money or quiet contracts (0.00001 after hours,
    or thousands of percent). Keep sensible readings (iv_src 'quote'); otherwise work the IV out from the
    option's mid price ('price'); failing that, borrow the nearest strike's of the same type ('nearby');
    failing that, None."""
    for x in rows:
        if iv_ok(x.get("iv")):
            x["iv_src"] = "quote"
            continue
        v = implied_vol(x.get("mid"), S, x["strike"], T, r, x["type"] == "call") if (S and T > 0) else None
        x["iv"], x["iv_src"] = (v, "price") if iv_ok(v) else (None, None)
    for x in rows:
        if x["iv"] is None:
            near = [y for y in rows if y["type"] == x["type"] and y.get("iv_src") in ("quote", "price")]
            if near:
                n = min(near, key=lambda y: abs(y["strike"] - x["strike"]))
                x["iv"], x["iv_src"] = n["iv"], "nearby"


def year_frac(expiry, now=None):
    now = now or timeutil.now()
    close = dt.datetime.combine(expiry, marketcal.close_time_et(expiry), timeutil.ET)
    return max((close - now).total_seconds(), 0) / (365 * 86400)


def occ(symbol, expiry, type_, strike):
    e = expiry if isinstance(expiry, dt.date) else dt.date.fromisoformat(expiry)
    return f"{symbol.upper()}{e.strftime('%y%m%d')}{'C' if type_ == 'call' else 'P'}{int(round(strike * 1000)):08d}"


def _num(v):
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    return None if math.isnan(f) else f


def mid_of(bid, ask, last=None):
    if bid and ask and ask >= bid:
        return round((bid + ask) / 2 + 1e-9, 2)
    if ask and not bid:
        return round(ask / 2 + 1e-9, 2)
    return last


# ---------------------------------------------------------------- Yahoo
class YahooProvider:
    name = "Yahoo Finance (~15 min delayed)"
    demo = False

    def __init__(self, symbol=SYMBOL):
        try:
            import yfinance as yf  # noqa: F401
        except ImportError as e:  # pragma: no cover - depends on install
            raise DataError("The yfinance package isn't installed. Run ./install.sh again.") from e
        self.yf = yf
        self.symbol = symbol

    def _t(self, sym=None):
        return self.yf.Ticker(sym or self.symbol)

    def underlying(self):
        fi = self._t().fast_info
        price = _num(fi["last_price"])
        prev = _num(fi["previous_close"])
        if not price:
            raise DataError(f"Yahoo returned no price for {self.symbol}.")
        return {"price": price, "prev_close": prev, "bid": None, "ask": None, "asof": timeutil.iso()}

    def stock_bidask(self):
        """Share bid/ask (slower call; only used when a share ticket is open)."""
        info = self._t().info
        return _num(info.get("bid")) or None, _num(info.get("ask")) or None

    def expirations(self):
        exps = list(self._t().options)
        if not exps:
            raise DataError(f"Yahoo returned no expirations for {self.symbol}.")
        return exps

    def chain(self, expiry):
        oc = self._t().option_chain(expiry)
        rows = []
        for df, typ in ((oc.calls, "call"), (oc.puts, "put")):
            for r in df.to_dict("records"):
                rows.append({
                    "type": typ, "strike": _num(r.get("strike")), "bid": _num(r.get("bid")) or 0.0,
                    "ask": _num(r.get("ask")) or 0.0, "last": _num(r.get("lastPrice")),
                    "iv": _num(r.get("impliedVolatility")), "volume": int(_num(r.get("volume")) or 0),
                    "oi": int(_num(r.get("openInterest")) or 0),
                })
        if not rows:
            raise DataError(f"Yahoo returned an empty chain for {expiry}.")
        return rows

    def daily_closes(self, start, end, symbol=None):
        h = self._t(symbol).history(start=start, end=end + dt.timedelta(days=1), auto_adjust=False)
        out = {}
        if h is not None and not h.empty:
            for idx, row in h.iterrows():
                c = _num(row.get("Close"))
                if c:
                    out[idx.date().isoformat()] = c
        return out

    def daily_bars(self, symbol, start, end):
        """Daily bars [{day, high, low, close}] (split-adjusted), including today's partial bar when trading."""
        h = self._t(symbol).history(start=start, end=end + dt.timedelta(days=1), auto_adjust=False)
        out = []
        if h is not None and not h.empty:
            for idx, row in h.iterrows():
                c, hi, lo = _num(row.get("Close")), _num(row.get("High")), _num(row.get("Low"))
                if c and hi and lo:
                    out.append({"day": idx.date().isoformat(), "high": hi, "low": lo, "close": c})
        return out

    def fear_greed(self, start):
        from .indicators import fetch_cnn
        return fetch_cnn(start)

    def earnings_dates(self, symbols):
        """{symbol: [upcoming earnings dates]} from Yahoo's calendar; symbols that fail are left out."""
        out = {}
        for sym in symbols:
            try:
                cal = self._t(sym).calendar or {}
                ds = cal.get("Earnings Date") or []
                ds = ds if isinstance(ds, (list, tuple)) else [ds]
                got = [d if isinstance(d, dt.date) else getattr(d, "date", lambda: None)() for d in ds]
                if got and got[0]:
                    out[sym] = [got[0]]   # Yahoo sometimes gives a range; the first date is the expected one
            except Exception as e:  # noqa: BLE001
                log.warning("earnings %s: %s", sym, e)
        return out

    def market_snapshot(self, symbols):
        """{symbol: {price, prev_close, market_cap}} for the Market tab; symbols that fail are left out."""
        out = {}
        for sym in symbols:
            try:
                fi = self._t(sym).fast_info
                p, prev = _num(fi["last_price"]), _num(fi["previous_close"])
                cap = None
                try:
                    cap = _num(fi["market_cap"])
                except Exception:  # noqa: BLE001 - ETFs have none
                    pass
                if p:
                    out[sym] = {"price": p, "prev_close": prev, "market_cap": cap}
            except Exception as e:  # noqa: BLE001
                log.warning("snapshot %s: %s", sym, e)
        return out

    def earnings_history(self, symbols, limit=12):
        """{symbol: [past and upcoming earnings dates]} from Yahoo's earnings history; failures left out."""
        out = {}
        for sym in symbols:
            try:
                df = self._t(sym).get_earnings_dates(limit=limit)
                if df is not None and len(df):
                    out[sym] = sorted({ts.date() for ts in df.index})
            except Exception as e:  # noqa: BLE001
                log.warning("earnings history %s: %s", sym, e)
        return out

    def dividends(self):
        s = self._t().dividends
        return [(idx.date(), float(v)) for idx, v in s.items()] if s is not None else []

    def splits(self):
        s = self._t().splits
        return [(idx.date(), float(v)) for idx, v in s.items()] if s is not None else []

    def next_ex_dividend(self):
        try:
            cal = self._t().calendar or {}
            d = cal.get("Ex-Dividend Date")
            return d if isinstance(d, dt.date) else None
        except Exception:
            return None

    def irx(self, start, end):
        """^IRX daily closes (13-week T-bill discount rate, in percent)."""
        return self.daily_closes(start, end, symbol="^IRX")


# ---------------------------------------------------------------- Demo
class DemoProvider:
    """Synthetic data priced with Black-Scholes and a put skew. Deterministic per day."""
    name = "Demo data (synthetic, not real prices)"
    demo = True

    def __init__(self, symbol=SYMBOL, base=56.56, fail=()):
        self.symbol = symbol
        self.base = base
        self.fail = set(fail)  # names of methods that should raise (for tests)

    def _chk(self, name):
        if name in self.fail:
            raise DataError(f"Demo failure in {name}.")

    def _price_on(self, d):
        rnd = random.Random(d.toordinal())
        k = (d - dt.date(2026, 1, 1)).days
        return round(self.base * (1 + 0.06 * math.sin(k / 9.0) + 0.02 * math.sin(k / 2.3)) + rnd.uniform(-.3, .3), 2)

    def underlying(self):
        self._chk("underlying")
        today = timeutil.today_ct()
        p = self._price_on(today)
        prev = self._price_on(marketcal.prev_trading_day(today))
        return {"price": p, "prev_close": prev, "bid": round(p - .01, 2), "ask": round(p + .01, 2),
                "asof": timeutil.iso()}

    def expirations(self):
        self._chk("expirations")
        today = timeutil.today_ct()
        out = []
        d = today + dt.timedelta(days=(4 - today.weekday()) % 7)
        for i in range(8):
            f = d + dt.timedelta(weeks=i)
            out.append(f if marketcal.is_trading_day(f) else marketcal.prev_trading_day(f))
        for m in range(3, 6):
            y, mo = today.year + (today.month + m - 1) // 12, (today.month + m - 1) % 12 + 1
            third = marketcal._nth_weekday(y, mo, 4, 3)
            out.append(third)
        out.append(marketcal._nth_weekday(today.year + 1, 1, 4, 3))
        out.append(marketcal._nth_weekday(today.year + 2, 1, 4, 3))
        return sorted({x.isoformat() for x in out if x >= today})

    def chain(self, expiry):
        self._chk("chain")
        S = self.underlying()["price"]
        e = dt.date.fromisoformat(expiry)
        T = year_frac(e) + 0.25 / 365
        rows = []
        for k in range(math.floor(S * 0.5), math.ceil(S * 1.5) + 1):
            K = float(k)
            m = math.log(K / S)
            iv = max(0.35, 0.62 - 0.55 * m + 0.9 * m * m)
            for typ in ("call", "put"):
                px, _ = bs(S, K, T, 0.042, iv, typ == "call")
                spread = max(0.01, round(px * 0.04, 2))
                bid = max(0.0, round(px - spread / 2, 2))
                ask = round(px + spread / 2, 2) if px > 0.005 else (0.01 if px > 0.0005 else 0.0)
                vol = int(4000 * math.exp(-abs(m) * 9) * (1.4 if typ == "put" else 1.0)) if bid > 0 else 0
                # Like Yahoo: far out-of-the-money puts often report a junk IV (exercises the repair in fix_ivs).
                rep = 0.00001 if (typ == "put" and K < S * 0.8) else round(iv, 4)
                rows.append({"type": typ, "strike": K, "bid": bid, "ask": ask, "last": round(px, 2), "iv": rep,
                             "volume": vol, "oi": 0})
        return rows

    def daily_closes(self, start, end, symbol=None):
        self._chk("daily_closes")
        out, d = {}, start
        while d <= end:
            if marketcal.is_trading_day(d) and (d < timeutil.today_ct() or timeutil.now_ct().hour >= 15):
                if symbol == "^IRX":
                    out[d.isoformat()] = 4.2
                elif symbol == "^VIX":
                    k = (d - dt.date(2026, 1, 1)).days
                    out[d.isoformat()] = round(19 + 6 * math.sin(k / 17.0) + 2 * math.sin(k / 3.7), 2)
                else:
                    out[d.isoformat()] = self._price_on(d)
            d += dt.timedelta(days=1)
        return out

    def daily_bars(self, symbol, start, end):
        self._chk("daily_bars")
        out = []
        for day, c in sorted(self.daily_closes(start, end).items()):
            rnd = random.Random(dt.date.fromisoformat(day).toordinal() * 7)
            out.append({"day": day, "high": round(c * (1 + rnd.uniform(.005, .03)), 2),
                        "low": round(c * (1 - rnd.uniform(.005, .03)), 2), "close": c})
        return out

    def fear_greed(self, start):
        self._chk("fear_greed")
        from .indicators import fg_rating
        hist, d, today = {}, start, timeutil.today_ct()
        while d <= today:
            if marketcal.is_trading_day(d):
                k = (d - dt.date(2026, 1, 1)).days
                hist[d.isoformat()] = round(50 + 28 * math.sin(k / 23.0) + 8 * math.sin(k / 5.1), 1)
            d += dt.timedelta(days=1)
        days = sorted(hist)
        score = hist[days[-1]]
        back = lambda n: hist[days[-1 - n]] if len(days) > n else None  # noqa: E731
        return {"score": score, "rating": fg_rating(score), "asof": timeutil.iso(), "previous_close": back(1),
                "week_ago": back(5), "month_ago": back(21), "year_ago": back(252), "history": hist}

    def earnings_dates(self, symbols):
        self._chk("earnings_dates")
        today = timeutil.today_ct()
        out = {}
        for i, sym in enumerate(symbols):
            d = today + dt.timedelta(days=3 + (len(symbols) - i) * 4)   # not in list order, so sorting shows
            while not marketcal.is_trading_day(d):
                d += dt.timedelta(days=1)
            out[sym] = [d]
        return out

    def market_snapshot(self, symbols):
        self._chk("market_snapshot")
        today, prev = timeutil.today_ct(), marketcal.prev_trading_day(timeutil.today_ct())
        caps = {"NVDA": 4.4e12, "AAPL": 3.9e12, "MSFT": 3.7e12, "AMZN": 2.4e12, "GOOGL": 2.3e12, "META": 1.8e12,
                "AVGO": 1.6e12, "TSLA": 1.4e12}
        out = {}
        for i, sym in enumerate(symbols):
            if sym == self.symbol:
                out[sym] = {"price": self._price_on(today), "prev_close": self._price_on(prev), "market_cap": None}
                continue
            base = 100 + 37 * i
            r = random.Random(f"{sym}{today}")
            pc = round(base * (1 + r.uniform(-.2, .2)), 2)
            out[sym] = {"price": round(pc * (1 + r.uniform(-.035, .035)), 2), "prev_close": pc, "market_cap": caps.get(sym)}
        return out

    def earnings_history(self, symbols, limit=12):
        self._chk("earnings_history")
        today = timeutil.today_ct()
        out = {}
        for i, sym in enumerate(symbols):
            ds, d = [], today + dt.timedelta(days=3 + i * 4)
            for _ in range(limit):
                x = d
                while not marketcal.is_trading_day(x):
                    x += dt.timedelta(days=1)
                ds.append(x)
                d -= dt.timedelta(days=91)
            out[sym] = sorted(ds)
        return out

    def dividends(self):
        return []

    def splits(self):
        return []

    def next_ex_dividend(self):
        return None

    def stock_bidask(self):
        p = self.underlying()["price"]
        return round(p - .01, 2), round(p + .01, 2)

    def irx(self, start, end):
        self._chk("irx")
        return self.daily_closes(start, end, symbol="^IRX")


# ---------------------------------------------------------------- rates
class Rates:
    """Daily 3-month T-bill rates stored in the `rates` table; source order Alpha Vantage -> ^IRX -> manual."""

    AV_URL = "https://www.alphavantage.co/query"

    def __init__(self, db, settings, provider):
        self.db, self.settings, self.provider = db, settings, provider

    def _fetch_av(self, key):
        qs = urllib.parse.urlencode({"function": "TREASURY_YIELD", "interval": "daily", "maturity": "3month",
                                     "apikey": key})
        with urllib.request.urlopen(f"{self.AV_URL}?{qs}", timeout=20) as r:
            js = json.loads(r.read().decode())
        if "data" not in js:
            msg = js.get("Information") or js.get("Note") or js.get("Error Message") or "unexpected reply"
            raise DataError(f"Alpha Vantage: {msg}")
        out = {}
        for row in js["data"]:
            v = _num(row.get("value"))
            if v is not None:
                out[row["date"]] = v
        if not out:
            raise DataError("Alpha Vantage returned no rates.")
        return out

    def store(self, series, source):
        with self.db.tx():
            for day, rate in series.items():
                self.db.x("INSERT OR REPLACE INTO rates(day,rate,source) VALUES(?,?,?)", (day, rate, source))

    def refresh(self, since):
        """Fetch rates back to `since`. Returns (rate, day, source). Raises DataError if nothing works."""
        errs = []
        key = (self.settings.get("av_key") or "").strip()
        if key and not getattr(self.provider, "demo", False):
            for attempt in range(2):
                try:
                    s = self._fetch_av(key)
                    self.store({d: v for d, v in s.items() if d >= (since - dt.timedelta(days=10)).isoformat()},
                               "Alpha Vantage 3-mo Treasury")
                    return self.latest()
                except Exception as e:  # noqa: BLE001
                    errs.append(str(e).rstrip("."))
                    time.sleep(0.5 * (attempt + 1))
        elif not key:
            errs.append("no Alpha Vantage key set (Settings)")
        for attempt in range(2):
            try:
                s = self.provider.irx(since - dt.timedelta(days=10), timeutil.today_ct())
                if not s:
                    raise DataError("^IRX returned no data.")
                self.store(s, "^IRX via Yahoo")
                return self.latest()
            except Exception as e:  # noqa: BLE001
                errs.append(f"^IRX: {str(e).rstrip('.')}")
        man = self.settings.get("manual_rate")
        if man is not None:
            self.store({timeutil.today_ct().isoformat(): float(man)}, "manual")
            return self.latest()
        raise DataError(" · ".join(dict.fromkeys(errs)) + ".")

    def latest(self):
        r = self.db.one("SELECT day, rate, source FROM rates ORDER BY day DESC LIMIT 1")
        return (r["rate"], r["day"], r["source"]) if r else (None, None, None)

    def for_day(self, d):
        iso = d.isoformat() if not isinstance(d, str) else d
        r = self.db.one("SELECT rate FROM rates WHERE day<=? ORDER BY day DESC LIMIT 1", (iso,))
        if r:
            return r[0]
        r = self.db.one("SELECT rate FROM rates ORDER BY day LIMIT 1")
        if r:
            return r[0]
        man = self.settings.get("manual_rate")
        return float(man) if man is not None else 0.0


# ---------------------------------------------------------------- quotes
class Quotes:
    """Chains and the underlying with a short cache, plus a last-good-quote store so chains stay populated at
    night and when Yahoo hiccups."""

    CACHE_S = 60
    STALE_S = 15 * 60

    def __init__(self, db, provider, rates):
        self.db, self.p, self.rates = db, provider, rates
        self._lock = threading.Lock()
        self._chains = {}
        self._und = None
        self._exps = None

    # underlying ---------------------------------------------------------------------------------------
    def underlying(self, fresh=False):
        with self._lock:
            if self._und and not fresh and time.time() - self._und["_t"] < self.CACHE_S:
                return self._und
        try:
            u = self.p.underlying()
            u["_t"] = time.time()
            u["stale"] = False
            self.db.x("INSERT OR REPLACE INTO prices(symbol,day,close) VALUES(?,?,?)",
                      ("_last_" + SYMBOL, timeutil.today_ct().isoformat(), u["price"]))
            self.db.x("INSERT OR REPLACE INTO quotes(contract,symbol,bid,ask,last,asof) VALUES(?,?,?,?,?,?)",
                      ("_U_" + SYMBOL, SYMBOL, u.get("bid"), u.get("ask"), u["price"], u["asof"]))
            meta = json.dumps({"prev_close": u.get("prev_close")})
            self.db.x("INSERT OR REPLACE INTO quotes(contract,symbol,iv,last,asof,type) VALUES(?,?,?,?,?,?)",
                      ("_UP_" + SYMBOL, SYMBOL, None, u.get("prev_close"), u["asof"], meta))
        except Exception as e:  # noqa: BLE001
            log.warning("underlying failed: %s", e)
            r = self.db.one("SELECT * FROM quotes WHERE contract=?", ("_U_" + SYMBOL,))
            if not r:
                raise DataError(f"No price for {SYMBOL}: {e}")
            pr = self.db.one("SELECT last FROM quotes WHERE contract=?", ("_UP_" + SYMBOL,))
            u = {"price": r["last"], "bid": r["bid"], "ask": r["ask"], "asof": r["asof"],
                 "prev_close": pr[0] if pr else None, "_t": time.time(), "stale": True, "error": str(e)}
        with self._lock:
            self._und = u
        return u

    def set_manual_price(self, price):
        u = {"price": float(price), "bid": None, "ask": None, "prev_close": None, "asof": timeutil.iso(),
             "_t": time.time(), "stale": True, "manual": True}
        with self._lock:
            self._und = u
        self.db.x("INSERT OR REPLACE INTO quotes(contract,symbol,last,asof) VALUES(?,?,?,?)",
                  ("_U_" + SYMBOL, SYMBOL, float(price), u["asof"]))
        return u

    def expirations(self, fresh=False):
        if self._exps and not fresh:
            return self._exps
        today = timeutil.today_ct().isoformat()
        try:
            ex = [e for e in self.p.expirations() if e >= today]
            self.db.x("INSERT OR REPLACE INTO quotes(contract,symbol,type,asof) VALUES(?,?,?,?)",
                      ("_EXPS_" + SYMBOL, SYMBOL, json.dumps(ex), timeutil.iso()))
        except Exception as e:  # noqa: BLE001
            r = self.db.one("SELECT type FROM quotes WHERE contract=?", ("_EXPS_" + SYMBOL,))
            if not r:
                raise DataError(f"No expiration list: {e}")
            ex = [x for x in json.loads(r[0]) if x >= today]
        self._exps = ex
        return ex

    # chains -------------------------------------------------------------------------------------------
    def chain(self, expiry, fresh=False):
        """Returns {'rows': [...], 'asof', 'stale', 'error'} with mid and delta filled in."""
        with self._lock:
            c = self._chains.get(expiry)
            if c and not fresh and time.time() - c["_t"] < self.CACHE_S:
                return c
        err = None
        try:
            rows = self.p.chain(expiry)
            asof = timeutil.iso()
            stale = False
            with self.db.tx():
                for r in rows:
                    key = occ(SYMBOL, expiry, r["type"], r["strike"])
                    if r["bid"] or r["ask"]:
                        self.db.x("INSERT OR REPLACE INTO quotes(contract,symbol,expiry,type,strike,bid,ask,last,iv,asof)"
                                  " VALUES(?,?,?,?,?,?,?,?,?,?)",
                                  (key, SYMBOL, expiry, r["type"], r["strike"], r["bid"], r["ask"], r["last"], r["iv"], asof))
                    else:
                        # Yahoo often blanks bid/ask outside market hours: fall back to the last good quote.
                        g = self.db.one("SELECT bid, ask, iv, asof FROM quotes WHERE contract=?", (key,))
                        if g and (g["bid"] or g["ask"]):
                            r.update(bid=g["bid"] or 0.0, ask=g["ask"] or 0.0, iv=r.get("iv") or g["iv"], asof=g["asof"],
                                     fallback=True)
                            stale = True
        except Exception as e:  # noqa: BLE001
            log.warning("chain %s failed: %s", expiry, e)
            err = str(e)
            got = self.db.q("SELECT * FROM quotes WHERE symbol=? AND expiry=?", (SYMBOL, expiry))
            if not got:
                raise DataError(f"No quotes for {expiry}: {e}")
            rows = [{"type": g["type"], "strike": g["strike"], "bid": g["bid"] or 0.0, "ask": g["ask"] or 0.0,
                     "last": g["last"], "iv": g["iv"], "asof": g["asof"], "fallback": True} for g in got]
            asof = min(g["asof"] for g in got)
            stale = True
        self._enrich(rows, expiry)
        out = {"rows": rows, "asof": asof, "stale": stale, "error": err, "_t": time.time()}
        with self._lock:
            self._chains[expiry] = out
        return out

    def _enrich(self, rows, expiry):
        S = (self._und or {}).get("price")
        if S is None:
            try:
                S = self.underlying()["price"]
            except DataError:
                S = None
        r = (self.rates.for_day(timeutil.today_ct()) or 4.0) / 100
        T = year_frac(dt.date.fromisoformat(expiry))
        for x in rows:
            x["mid"] = mid_of(x["bid"], x["ask"], x.get("last")) or 0.0
        fix_ivs(rows, S, T, r)
        for x in rows:
            iv = x.get("iv")
            x["delta"] = round(bs(S, x["strike"], T, r, iv, x["type"] == "call")[1], 2) if (S and iv) else None

    def quote(self, expiry, type_, strike, fresh=True):
        c = self.chain(expiry, fresh=fresh)
        for x in c["rows"]:
            if x["type"] == type_ and abs(x["strike"] - float(strike)) < 1e-6:
                q = dict(x)
                q.update(asof=x.get("asof") or c["asof"], stale=c["stale"] and bool(x.get("asof")) or c["error"] is not None,
                         expiry=expiry)
                return q
        return None

    def share_quote(self, fresh=False):
        u = self.underlying(fresh=fresh)
        bid = ask = None
        if marketcal.is_open(timeutil.now()):
            try:
                bid, ask = self.p.stock_bidask()
            except Exception:  # noqa: BLE001
                pass
        if not bid or not ask or ask < bid:
            bid = ask = u["price"]
        return {"bid": bid, "ask": ask, "mid": round((bid + ask) / 2 + 1e-9, 2), "asof": u["asof"],
                "stale": u.get("stale"), "last": u["price"]}

    def is_too_old(self, asof_iso):
        """During market hours, quotes older than 15 minutes block trading until refreshed."""
        now = timeutil.now()
        if not marketcal.is_open(now):
            return False
        return (now - timeutil.parse(asof_iso)).total_seconds() > self.STALE_S

    def invalidate(self):
        with self._lock:
            self._chains.clear()
            self._und = None

ghost_trader/marketcal.py:
"""Built-in NYSE calendar: holidays, early closes, market hours.

Holidays follow NYSE rule 7.2 (Saturday holidays observed Friday, Sunday holidays observed Monday,
except New Year's Day on a Saturday, which is not observed). One-off closures are listed in
SPECIAL_CLOSURES and kept current through app updates.
"""
import datetime as dt
from functools import lru_cache

from .timeutil import ET, CT

D = dt.date

SPECIAL_CLOSURES = {
    D(2012, 10, 29): "Hurricane Sandy",
    D(2012, 10, 30): "Hurricane Sandy",
    D(2018, 12, 5): "National Day of Mourning (George H.W. Bush)",
    D(2025, 1, 9): "National Day of Mourning (Jimmy Carter)",
}

OPEN_ET = dt.time(9, 30)
CLOSE_ET = dt.time(16, 0)
EARLY_CLOSE_ET = dt.time(13, 0)


def _nth_weekday(year, month, weekday, n):
    d = D(year, month, 1)
    d += dt.timedelta(days=(weekday - d.weekday()) % 7)
    return d + dt.timedelta(weeks=n - 1)


def _last_weekday(year, month, weekday):
    nxt = D(year + (month == 12), month % 12 + 1, 1)
    d = nxt - dt.timedelta(days=1)
    return d - dt.timedelta(days=(d.weekday() - weekday) % 7)


def _easter(year):
    a = year % 19
    b, c = divmod(year, 100)
    d, e = divmod(b, 4)
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = divmod(c, 4)
    ll = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * ll) // 451
    month = (h + ll - 7 * m + 114) // 31
    day = (h + ll - 7 * m + 114) % 31 + 1
    return D(year, month, day)


def _observed(d):
    if d.weekday() == 5:
        return d - dt.timedelta(days=1)
    if d.weekday() == 6:
        return d + dt.timedelta(days=1)
    return d


@lru_cache(maxsize=None)
def holidays(year):
    """{date: name} of full-day NYSE closures in a year."""
    h = {}
    ny = D(year, 1, 1)
    if ny.weekday() == 6:
        h[D(year, 1, 2)] = "New Year's Day (observed)"
    elif ny.weekday() != 5:
        h[ny] = "New Year's Day"
    h[_nth_weekday(year, 1, 0, 3)] = "Martin Luther King Jr. Day"
    h[_nth_weekday(year, 2, 0, 3)] = "Washington's Birthday"
    h[_easter(year) - dt.timedelta(days=2)] = "Good Friday"
    h[_last_weekday(year, 5, 0)] = "Memorial Day"
    if year >= 2022:
        h[_observed(D(year, 6, 19))] = "Juneteenth"
    h[_observed(D(year, 7, 4))] = "Independence Day"
    h[_nth_weekday(year, 9, 0, 1)] = "Labor Day"
    h[_nth_weekday(year, 11, 3, 4)] = "Thanksgiving Day"
    h[_observed(D(year, 12, 25))] = "Christmas Day"
    # New Year's of next year falling on a Saturday is not observed on Dec 31 (rule 7.2).
    for d, name in SPECIAL_CLOSURES.items():
        if d.year == year:
            h[d] = name
    return h


def holiday_name(d):
    return holidays(d.year).get(d)


def is_trading_day(d):
    return d.weekday() < 5 and d not in holidays(d.year)


@lru_cache(maxsize=None)
def early_closes(year):
    out = {}
    j3 = D(year, 7, 3)
    if j3.weekday() <= 3 and is_trading_day(j3):
        out[j3] = "Day before Independence Day"
    out[_nth_weekday(year, 11, 3, 4) + dt.timedelta(days=1)] = "Day after Thanksgiving"
    c24 = D(year, 12, 24)
    if c24.weekday() <= 3 and is_trading_day(c24):
        out[c24] = "Christmas Eve"
    return out


def close_time_et(d):
    return EARLY_CLOSE_ET if d in early_closes(d.year) else CLOSE_ET


def prev_trading_day(d, inclusive=False):
    if not inclusive:
        d -= dt.timedelta(days=1)
    while not is_trading_day(d):
        d -= dt.timedelta(days=1)
    return d


def next_trading_day(d, inclusive=False):
    if not inclusive:
        d += dt.timedelta(days=1)
    while not is_trading_day(d):
        d += dt.timedelta(days=1)
    return d


def market_status(ts):
    """('open'|'closed', label) for an aware datetime."""
    e = ts.astimezone(ET)
    d = e.date()
    if not is_trading_day(d):
        why = holiday_name(d) or "weekend"
        return "closed", f"Market closed ({why})" if holiday_name(d) else "Market closed"
    if OPEN_ET <= e.time() < close_time_et(d):
        return "open", "Market open" + (" · early close 12:00 PM CT" if d in early_closes(d.year) else "")
    return "closed", "Market closed"


def is_open(ts):
    return market_status(ts)[0] == "open"


def last_close_dt(ts):
    """Aware datetime of the most recent regular-session close at or before ts."""
    e = ts.astimezone(ET)
    d = e.date()
    if is_trading_day(d) and e.time() >= close_time_et(d):
        day = d
    else:
        day = prev_trading_day(d)
    return dt.datetime.combine(day, close_time_et(day), ET)


def interest_pay_date(year, month):
    """The 15th, or the previous business day if the 15th is a weekend or market holiday."""
    return prev_trading_day(D(year, month, 15), inclusive=True)


def pay_dates_between(start, end):
    """Pay dates p with start < p <= end."""
    out = []
    y, m = start.year, start.month
    while D(y, m, 1) <= end:
        p = interest_pay_date(y, m)
        if start < p <= end:
            out.append(p)
        y, m = (y + 1, 1) if m == 12 else (y, m + 1)
    return out


def next_pay_date(after):
    """First pay date strictly after `after`... or on it if it is one and not yet paid (caller decides)."""
    y, m = after.year, after.month
    for _ in range(3):
        p = interest_pay_date(y, m)
        if p > after:
            return p
        y, m = (y + 1, 1) if m == 12 else (y, m + 1)
    return None


def expiration_settle_ready(expiry, ts):
    """Expirations are processed at the first startup after 5 PM Central on expiration day."""
    c = ts.astimezone(CT)
    if c.date() > expiry:
        return True
    return c.date() == expiry and c.time() >= dt.time(17, 0)

ghost_trader/server.py:
"""Local HTTP server for the UI: static files plus a JSON API at POST /api/<name>.

Bound to 127.0.0.1 on a random port. API calls must carry the per-launch token (X-GT-Token header), so
other local programs can't drive the ledger."""
import json
import logging
import mimetypes
import secrets
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

from . import config

log = logging.getLogger("ghost_trader.server")
mimetypes.add_type("font/woff", ".woff")
mimetypes.add_type("text/javascript", ".js")


class Server:
    def __init__(self, app, port=0):
        self.app = app
        self.token = secrets.token_urlsafe(18)
        handler = _make_handler(app, self.token)
        self.httpd = ThreadingHTTPServer(("127.0.0.1", port), handler)
        self.httpd.daemon_threads = True
        self.port = self.httpd.server_address[1]
        self.thread = None

    @property
    def url(self):
        return f"http://127.0.0.1:{self.port}/?t={self.token}"

    def start(self):
        self.thread = threading.Thread(target=self.httpd.serve_forever, name="http", daemon=True)
        self.thread.start()
        return self

    def stop(self):
        try:
            self.httpd.shutdown()
            self.httpd.server_close()
        except Exception:  # noqa: BLE001
            pass


def _make_handler(app, token):
    methods = {n[4:]: getattr(app, n) for n in dir(app) if n.startswith("api_")}
    static_root = config.STATIC_DIR.resolve()

    class H(BaseHTTPRequestHandler):
        server_version = "GhostTrader"

        def log_message(self, fmt, *args):  # quiet
            log.debug("http " + fmt, *args)

        def _send(self, code, body, ctype="application/json"):
            data = body if isinstance(body, bytes) else body.encode()
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(data)

        def do_GET(self):
            path = urlparse(self.path).path
            if path in ("/", ""):
                path = "/index.html"
            if path == "/gate":
                return self._send(200, _GATE, "text/html; charset=utf-8")
            f = (static_root / path.lstrip("/")).resolve()
            if static_root not in f.parents or not f.is_file():
                return self._send(404, b"not found", "text/plain")
            ctype = mimetypes.guess_type(str(f))[0] or "application/octet-stream"
            if ctype.startswith("text/"):
                ctype += "; charset=utf-8"
            self._send(200, f.read_bytes(), ctype)

        def do_POST(self):
            path = urlparse(self.path).path
            if not path.startswith("/api/"):
                return self._send(404, b"{}")
            if self.headers.get("X-GT-Token") != token:
                return self._send(403, json.dumps({"error": "bad token"}))
            name = path[5:]
            fn = methods.get(name)
            if not fn:
                return self._send(404, json.dumps({"error": f"no such call: {name}"}))
            n = int(self.headers.get("Content-Length") or 0)
            try:
                args = json.loads(self.rfile.read(n) or b"{}") if n else {}
                res = fn(**args)
                self._send(200, json.dumps(res, default=str))
            except TypeError as e:
                log.exception("bad call %s", name)
                self._send(400, json.dumps({"error": f"bad call: {e}"}))
            except Exception as e:  # noqa: BLE001
                log.exception("api %s failed", name)
                self._send(500, json.dumps({"error": f"{type(e).__name__}: {e}"}))

    return H


# Page shown in Firefox when the native window failed and no dialog could ask first.
_GATE = """<!doctype html><meta charset=utf-8><title>Ghost Trader</title>
<body style="font:15px system-ui,sans-serif;background:#0f1115;color:#e6e8ec;display:flex;align-items:center;
justify-content:center;height:100vh;margin:0"><div style="max-width:520px;padding:24px;border:1px solid #2a2f3a;
