ghost_trader/timeutil.py:
"""Clock and time-display helpers. Everything is shown in Central time, with Eastern in parentheses
outside the ticket/confirm screens."""
import datetime as dt
from zoneinfo import ZoneInfo

CT = ZoneInfo("America/Chicago")
ET = ZoneInfo("America/New_York")

# Tests (and --demo) can pin "now" by setting this to an aware datetime.
_frozen = None


def freeze(when):
    """Pin the clock (aware datetime or None to unpin)."""
    global _frozen
    _frozen = when


def now():
    return _frozen if _frozen is not None else dt.datetime.now(dt.timezone.utc)


def now_ct():
    return now().astimezone(CT)


def today_ct():
    return now_ct().date()


def iso(ts=None):
    return (ts or now()).astimezone(dt.timezone.utc).isoformat(timespec="seconds")


def parse(ts):
    d = dt.datetime.fromisoformat(ts)
    return d if d.tzinfo else d.replace(tzinfo=dt.timezone.utc)


def _clock(t):
    return t.strftime("%I:%M %p").lstrip("0")


def fmt_ct(ts, with_et=True, with_date=False):
    """'3:15 PM CT (4:15 PM ET)' or with date 'Nov 11, 3:15 PM CT (4:15 PM ET)'."""
    if isinstance(ts, str):
        ts = parse(ts)
    c, e = ts.astimezone(CT), ts.astimezone(ET)
    s = (c.strftime("%b ") + str(c.day) + ", " if with_date else "") + _clock(c) + " CT"
    return s + (f" ({_clock(e)} ET)" if with_et else "")


def fmt_date(d):
    if isinstance(d, str):
        d = dt.date.fromisoformat(d[:10])
    return d.strftime("%b ") + str(d.day)


def fmt_exp(d):
    """'Fri Nov 20' (adds 'YY when not the current year)."""
    if isinstance(d, str):
        d = dt.date.fromisoformat(d)
    s = d.strftime("%a %b %d")
    if d.year != today_ct().year:
        s += d.strftime(" '%y")
    return s

ghost_trader/updater.py:
"""Updates through GitHub: the app follows tagged releases (vX.Y.Z) of its own git checkout.

Flow: fetch tags over the read-only deploy key -> newest release tag above the running version is offered at
startup with its change list (the tag message) -> on yes: back up the ledger, write a pending-update marker,
check out the tag, restart. The restarted app runs a self-check; if it fails, it checks the previous release
back out, restores the backup and logs the rollback. The launcher script does the same if the new version
crashes before it can check itself.
"""
import json
import logging
import os
import re
import subprocess
import sys

from . import __version__, config

log = logging.getLogger("ghost_trader.updater")
TAG_RE = re.compile(r"^v(\d+)\.(\d+)(?:\.(\d+))?$")
PUBLIC_REPO = "flak-daddy/ghost-trader-source"   # public mirror the AUR package builds from


def parse_version(s):
    m = TAG_RE.match(s.strip()) or TAG_RE.match("v" + s.strip())
    if not m:
        return None
    return tuple(int(x or 0) for x in m.groups())


def _git(*args, timeout=30):
    r = subprocess.run(["git", "-C", str(config.PROJECT_DIR), *args], capture_output=True, text=True, timeout=timeout)
    if r.returncode != 0:
        raise RuntimeError((r.stderr or r.stdout).strip() or f"git {' '.join(args)} failed")
    return r.stdout.strip()


def is_checkout():
    return (config.PROJECT_DIR / ".git").exists()


def marker_path():
    return config.data_dir() / "update-pending.json"


def current_ref():
    try:
        return _git("describe", "--tags", "--exact-match", "HEAD")
    except Exception:  # noqa: BLE001
        try:
            return _git("rev-parse", "--short", "HEAD")
        except Exception:  # noqa: BLE001
            return None


def local_edits():
    """Tracked files changed in the project folder (they would be overwritten by an update)."""
    out = _git("status", "--porcelain", "--untracked-files=no")
    return [ln[3:] for ln in out.splitlines() if ln.strip()]


def check():
    """Returns None, or {'tag','version','notes'} for the newest release newer than this one.
    Raises RuntimeError if GitHub can't be reached."""
    if not is_checkout():
        return None
    _git("fetch", "--tags", "--force", "--quiet", "origin", timeout=40)
    cur = parse_version(__version__)
    newer = sorted(((v, t) for t in _git("tag", "-l", "v*").splitlines() if (v := parse_version(t)) and v > cur),
                   reverse=True)
    if not newer:
        return None
    best = newer[0]
    notes = combined_notes([(t, _git("tag", "-l", "--format=%(contents)", t)) for _, t in newer])
    return {"tag": best[1], "version": ".".join(map(str, best[0])), "notes": notes, "skipped": len(newer) - 1}


MAX_NOTES = 12   # releases listed in full; anything older is summed up in one line


def combined_notes(items):
    """Change list for an update that may jump several releases: every release between this version and the
    newest, newest first, each under its own version line. `items` = [(tag, tag message), ...] newest first."""
    items = [(t, (n or "").strip()) for t, n in items]
    if len(items) == 1:
        return items[0][1]
    shown, rest = items[:MAX_NOTES], items[MAX_NOTES:]
    out = [f"This update includes {len(items)} releases since v{__version__}:"]
    for t, n in shown:
        lines = [ln for ln in n.splitlines() if ln.strip()] or ["- Maintenance release"]
        out.append(f"\n{t}\n" + "\n".join(lines))
    if rest:
        out.append(f"\n…and {len(rest)} earlier release{'s' if len(rest) > 1 else ''} ({rest[-1][0]} to {rest[0][0]}).")
    return "\n".join(out)


def check_public(timeout=10):
    """For package-manager installs: newest release tag in the public source repo, if newer than this one.
    Returns None or {'tag','version'}. Raises on network errors."""
    import urllib.request
    req = urllib.request.Request(f"https://api.github.com/repos/{PUBLIC_REPO}/tags?per_page=100",
                                 headers={"Accept": "application/vnd.github+json", "User-Agent": "ghost-trader"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        tags = [t["name"] for t in json.loads(r.read().decode())]
    cur = parse_version(__version__)
    best = max(((parse_version(t), t) for t in tags if parse_version(t)), default=None)
    if best and best[0] > cur:
        return {"tag": best[1], "version": ".".join(map(str, best[0]))}
    return None


def apply(tag, backup_fn):
    """Back up, mark, check out `tag`. Raises with a plain-English reason when it won't proceed."""
    edits = local_edits()
    if edits:
        raise RuntimeError(
            "Files in the project folder were edited locally, so the update won't overwrite them: "
            + ", ".join(edits[:6]) + ("…" if len(edits) > 6 else "")
            + ". Commit them to a branch on GitHub and open a pull request so they go through review, "
              "then restart.")
    prev = current_ref()
    backup = backup_fn()
    marker_path().write_text(json.dumps({"from": prev, "to": tag, "backup": str(backup),
                                         "from_version": __version__}))
    reqs_changed = bool(_git("diff", "--name-only", "HEAD", tag, "--", "requirements.txt"))
    _git("checkout", "--quiet", "--detach", tag)
    if reqs_changed:
        r = subprocess.run([sys.executable, "-m", "pip", "install", "--quiet", "-r",
                            str(config.PROJECT_DIR / "requirements.txt")], capture_output=True, text=True, timeout=600)
        if r.returncode != 0:
            _git("checkout", "--quiet", "--detach", prev)
            clear_pending()
            raise RuntimeError("The new version needs updated Python packages and installing them failed: "
                               + (r.stderr.strip().splitlines() or ["unknown error"])[-1]
                               + ". Stayed on the current version.")
    return {"from": prev, "to": tag, "backup": str(backup)}


def pending():
    p = marker_path()
    if not p.exists():
        return None
    try:
        return json.loads(p.read_text())
    except ValueError:
        return None


def clear_pending():
    marker_path().unlink(missing_ok=True)


def rollback(mark, restore_fn):
    """Check the previous release back out and restore the pre-update ledger backup."""
    if mark.get("from"):
        _git("checkout", "--quiet", "--detach", mark["from"])
    if mark.get("backup") and os.path.exists(mark["backup"]):
        restore_fn(mark["backup"])
    clear_pending()


def self_check():
    """Quick checks that the freshly-updated app can run. Returns a list of problems (empty = OK)."""
    problems = []
    try:
        from . import api, ledger, market, marketcal, perf, startup, server, window  # noqa: F401
    except Exception as e:  # noqa: BLE001
        problems.append(f"import failed: {e}")
    for f in ("index.html", "app.js", "app.css"):
        if not (config.STATIC_DIR / f).exists():
            problems.append(f"missing static/{f}")
    return problems


def restart(extra_env=None, args=None):
    env = dict(os.environ)
    env.update(extra_env or {})
    argv = [sys.executable, "-m", "ghost_trader"] + (args if args is not None else sys.argv[1:])
    os.execve(sys.executable, argv, env)

ghost_trader/window.py:
"""The app window and its fallback chain.

1. Own native window (pywebview + WebKitGTK). If it errors or stays blank for 10 s, retry once automatically with
   WEBKIT_DISABLE_DMABUF_RENDERER=1 (a known WebKitGTK fix on some Wayland/NVIDIA setups).
2. Chromium --app window, automatically, only if Chromium is installed.
3. Firefox: never automatic. A small GTK dialog asks first (terminal prompt, or a local "continue?" page, if GTK
   can't show anything).
Each fallback used is logged to History. In browser modes the app quits when the page stops sending heartbeats.
"""
import json
import logging
import os
import shutil
import subprocess
import sys
import threading
import time
from pathlib import Path

from . import APP_NAME, config, updater

log = logging.getLogger("ghost_trader.window")
LOAD_TIMEOUT = 10


class _Reasons:
    @staticmethod
    def get():
        try:
            return json.loads(os.environ.get("GT_FALLBACKS", "[]"))
        except ValueError:
            return []

    @staticmethod
    def env_with(reason, attempt, extra=None):
        env = {"GT_ATTEMPT": str(attempt), "GT_FALLBACKS": json.dumps(_Reasons.get() + [reason])}
        env.update(extra or {})
        return env


def _zenity_save(name):
    z = shutil.which("zenity")
    default = Path.home() / "Downloads" / name
    if z:
        r = subprocess.run([z, "--file-selection", "--save", "--confirm-overwrite", f"--filename={default}",
                            f"--title=Save {name}"], capture_output=True, text=True)
        return r.stdout.strip() or None
    default.parent.mkdir(parents=True, exist_ok=True)
    return str(default)


class BrowserAdapter:
    mode = "browser"

    def save_dialog(self, name):
        return _zenity_save(name)


class WebviewAdapter:
    mode = "native"

    def __init__(self, webview, win):
        self.webview, self.win = webview, win

    def save_dialog(self, name):
        wv = self.webview
        kind = getattr(getattr(wv, "FileDialog", None), "SAVE", None) or getattr(wv, "SAVE_DIALOG")
        res = self.win.create_file_dialog(kind, directory=str(Path.home()), save_filename=name)
        if not res:
            return None
        return res if isinstance(res, str) else res[0]


def _log_fallbacks(app, mode):
    reasons = _Reasons.get()
    if not reasons:
        return
    detail = " → ".join(reasons) + f". Now running in: {mode}."
    app.led_event_safe("Warning", "Window fallback used", detail, warning=True)


def _restart_env():
    return {"GT_ATTEMPT": "1", "GT_FALLBACKS": "[]"}


def run(app, server):
    attempt = int(os.environ.get("GT_ATTEMPT", "1"))
    if attempt <= 2:
        ok, reason = _try_webview(app, server)
        if ok:
            return 0
        nxt = {"WEBKIT_DISABLE_DMABUF_RENDERER": "1"} if attempt == 1 else {}
        label = f"native window failed ({reason})" + ("; retrying with WEBKIT_DISABLE_DMABUF_RENDERER=1"
                                                      if attempt == 1 else "")
        log.warning(label)
        server.stop()
        updater.restart(_Reasons.env_with(label, attempt + 1, nxt))
    if attempt == 3:
        ok, reason = _try_chromium(app, server)
        if ok:
            return 0
        server.stop()
        updater.restart(_Reasons.env_with(reason, 4))
    return _firefox(app, server)


def _try_webview(app, server):
    try:
        import webview
    except Exception as e:  # noqa: BLE001
        return False, f"pywebview not available: {e}"
    failed = {}
    try:
        win = webview.create_window(APP_NAME, server.url, width=1440, height=920, min_size=(960, 640),
                                    background_color="#0f1115")
    except Exception as e:  # noqa: BLE001
        return False, f"couldn't create the window: {e}"
    app.window = WebviewAdapter(webview, win)

    def watchdog():
        if not app.loaded.wait(LOAD_TIMEOUT):
            failed["reason"] = f"window stayed blank for {LOAD_TIMEOUT} s"
            try:
                win.destroy()
            except Exception:  # noqa: BLE001
                pass
        else:
            _log_fallbacks(app, "native window")

    def restart():
        try:
            win.destroy()
        except Exception:  # noqa: BLE001
            pass

    app.on_restart = restart
    threading.Thread(target=watchdog, daemon=True).start()
    try:
        webview.start(gui="gtk", private_mode=False, storage_path=str(config.data_dir() / "webview"))
    except Exception as e:  # noqa: BLE001
        failed["reason"] = f"window error: {e}"
    if app.restart_requested:
        server.stop()
        updater.restart(_restart_env())
    if failed:
        return False, failed["reason"]
    server.stop()
    return True, None


def _chromium_bin():
    for b in ("chromium", "chromium-browser"):
        p = shutil.which(b)
        if p:
            return p
    return None


def _heartbeat_loop(app, proc=None, grace=25):
    while True:
        time.sleep(2)
        if app.restart_requested:
            if proc:
                proc.terminate()
            updater.restart(_restart_env())
        if proc is not None and proc.poll() is not None:
            return
        if time.time() - app.last_beat > grace:
            return


def _try_chromium(app, server):
    b = _chromium_bin()
    if not b:
        return False, "Chromium isn't installed (skipped)"
    app.window = BrowserAdapter()
    prof = config.data_dir() / "chromium-profile"
    proc = subprocess.Popen([b, f"--app={server.url}", f"--user-data-dir={prof}", "--class=GhostTrader",
                             "--no-first-run", "--window-size=1440,920"], stdout=subprocess.DEVNULL,
                            stderr=subprocess.DEVNULL, start_new_session=True)
    if not app.loaded.wait(LOAD_TIMEOUT + 10):
        proc.terminate()
        return False, "Chromium app window didn't load"
    _log_fallbacks(app, "Chromium app window")
    _heartbeat_loop(app, proc)
    if proc.poll() is None:
        proc.terminate()
    server.stop()
    return True, None


def _ask_gtk(reason):
    try:
        import gi
        gi.require_version("Gtk", "3.0")
        from gi.repository import Gtk
    except Exception:  # noqa: BLE001
        return None
    try:
        d = Gtk.MessageDialog(message_type=Gtk.MessageType.QUESTION, buttons=Gtk.ButtonsType.NONE,
                              text="The Ghost Trader window didn't start as designed")
        d.format_secondary_text(f"{reason}.\n\nOpen Ghost Trader in Firefox instead?")
        d.add_button("Quit", Gtk.ResponseType.CANCEL)
        d.add_button("Open in Firefox", Gtk.ResponseType.OK)
        d.set_title(APP_NAME)
        resp = d.run()
        d.destroy()
        while Gtk.events_pending():
            Gtk.main_iteration()
        return resp == Gtk.ResponseType.OK
    except Exception:  # noqa: BLE001
        return None


def _firefox(app, server):
    reasons = _Reasons.get()
    reason = reasons[-1] if reasons else "the native window failed"
    ff = shutil.which("firefox")
    if not ff:
        print(f"{APP_NAME} couldn't open a window: " + "; ".join(reasons or [reason])
              + ". Firefox isn't installed either. See logs/ghost-trader.log.", file=sys.stderr)
        return 3
    answer = _ask_gtk(reason)
    if answer is None and sys.stdin and sys.stdin.isatty():
        try:
            answer = input(f"{APP_NAME}: {reason}. Open in Firefox instead? [y/N] ").strip().lower().startswith("y")
        except EOFError:
            answer = False
    app.window = BrowserAdapter()
    if answer is None:
        # Nothing could ask: open a local page that asks, and don't load the app until Continue is clicked.
        app.gate = threading.Event()
        app.gate_answer = None
        subprocess.Popen([ff, "--new-window", server.url.replace("/?", "/gate?")], stdout=subprocess.DEVNULL,
                         stderr=subprocess.DEVNULL, start_new_session=True)
        app.gate.wait()
        answer = app.gate_answer == "continue"
    else:
        if answer:
            subprocess.Popen([ff, "--new-window", server.url], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             start_new_session=True)
    if not answer:
        server.stop()
        return 0
    if not app.loaded.wait(60):
        server.stop()
        return 4
    os.environ["GT_FALLBACKS"] = json.dumps(reasons + ["opened in Firefox after asking"])
    _log_fallbacks(app, "Firefox")
    _heartbeat_loop(app)
    server.stop()
    return 0

gt_web.py:
"""Ghost Trader Lite: the real app running in the browser under Pyodide, on synthetic data.

Loaded by web/boot.js. Patches the few desktop-only pieces (threads, subprocess, notifications,
startup dialogs), seeds a lived-in demo run relative to today, and exposes `dispatch(name, json)`
which answers the UI's /api/<name> calls exactly like server.py does.
Also importable under plain CPython for tests (tests/test_web.py).
"""
import json
import logging
import math
import os
import random
import subprocess
import threading

HOME = os.environ.setdefault("GHOST_TRADER_HOME", "/gtdata")
WEB = True

# ---------------------------------------------------------------- desktop-only pieces
# Pyodide can't start threads. Run every background job to completion right away instead;
# the app's background work (startup steps, indicator warm-up, earnings fetch) is quick on demo data.
_real_start = threading.Thread.start


def _sync_start(self):
    try:
        if self._target:
            self._target(*self._args, **self._kwargs)
        else:
            self.run()
    except Exception:  # noqa: BLE001
        logging.getLogger("gt.web").exception("background job failed")


def patch_threads():
    threading.Thread.start = _sync_start
    threading.Timer.start = lambda self: None  # only used for restart-after-restore; no-op in the browser


class _NoProc:
    def __init__(self, *a, **k):
        self.returncode = 0

    def wait(self, *a, **k):
        return 0

    def communicate(self, *a, **k):
        return (b"", b"")


def patch_desktop():
    subprocess.Popen = _NoProc
    subprocess.run = lambda *a, **k: subprocess.CompletedProcess(a, 1, b"", b"")
    from ghost_trader import notify, startup

    notify.send = lambda title, body="", *a, **k: (False, "Desktop notifications are in the desktop app only.")
    if hasattr(notify, "ensure_timer"):
        notify.ensure_timer = lambda *a, **k: None

    # Startup dialogs wait for an answer from another thread; here nothing else can answer.
    # Pick the "keep going" option and log it, like choosing it by hand.
    def auto_ask(self, kind, title, what, options, **extra):
        prefer = ("skip", "later", "manual", "ok")
        pick = next((o["id"] for p in prefer for o in options if o["id"] == p), options[0]["id"])
        self.warnings.append(f"{title} ({pick}, automatic in the web demo)")
        return pick, None

    startup.Startup._ask = auto_ask

    # WAL needs shared memory the browser's file system doesn't have, and it would split the ledger
    # across two files when saving to browser storage. Use a plain rollback journal instead.
    from ghost_trader import db as dbm
    if not getattr(dbm.DB.__init__, "_web", False):
        orig = dbm.DB.__init__

        def init(self, *a, **k):
            orig(self, *a, **k)
            self.conn.execute("PRAGMA journal_mode=DELETE")
        init._web = True
        dbm.DB.__init__ = init


# ---------------------------------------------------------------- data
def make_provider():
    from ghost_trader import marketcal, timeutil
    from ghost_trader.market import DemoProvider

    class WebDemoProvider(DemoProvider):
        """DemoProvider, plus a gentle intraday drift so prices move with the clock while the market is open."""
        name = "Demo data (synthetic, moves with the clock)"

        def _intraday(self, d):
            now = timeutil.now_ct()
            if d != now.date() or not marketcal.is_trading_day(d):
                return 0.0
            open_ = now.replace(hour=8, minute=30, second=0, microsecond=0)
            mins = max(0.0, min((now - open_).total_seconds() / 60, 390.0))
            seed = d.toordinal()
            a, b = random.Random(seed).uniform(-1, 1), random.Random(seed + 7).uniform(0, 6.28)
            # smooth path: 0 at the open, back to the day's close at 3 PM, wiggling in between
            env = math.sin(mins / 390 * math.pi)
            return round(self.base * 0.012 * env * (a + 0.35 * math.sin(mins / 37 + b)), 2)

        def underlying(self):
            u = super().underlying()
            p = round(u["price"] + self._intraday(timeutil.today_ct()), 2)
            u.update(price=p, bid=round(p - .01, 2), ask=round(p + .01, 2))
            return u

        def chain(self, expiry):
            # DemoProvider.chain prices off self.underlying(), so it already follows the drift
            return super().chain(expiry)

    return WebDemoProvider()


# ---------------------------------------------------------------- the app
app = None
_methods = {}


def start():
    """Create the app (seeding a demo run on first visit). Returns 'seeded' or 'resumed'."""
    global app, _methods
    patch_threads()
    patch_desktop()
    logging.basicConfig(level=logging.WARNING)
    from ghost_trader import config
    from ghost_trader.api import App

    os.makedirs(HOME, exist_ok=True)
    fresh = not config.db_path().exists()
    if fresh:
        import seed_web
        seed_web.seed(make_provider())
    app = App(demo=True, provider=make_provider())
    app.web = True
    _methods = {n[4:]: getattr(app, n) for n in dir(app) if n.startswith("api_")}
    return "seeded" if fresh else "resumed"


def dispatch(name, args_json="{}"):
    """Same contract as server.py's POST /api/<name>: returns (status, json text)."""
    fn = _methods.get(name)
    if not fn:
        return 404, json.dumps({"error": f"no such call: {name}"})
    try:
        args = json.loads(args_json or "{}") or {}
        return 200, json.dumps(fn(**args), default=str)
    except TypeError as e:
        return 400, json.dumps({"error": f"bad call: {e}"})
    except Exception as e:  # noqa: BLE001
        logging.getLogger("gt.web").exception("api %s failed", name)
        return 500, json.dumps({"error": f"{type(e).__name__}: {e}"})


def reset():
    """Throw away this browser's demo ledger; the next start() seeds a new one."""
    global app
    import shutil
    try:
        app.db.close()
    except Exception:  # noqa: BLE001
        pass
    app = None
    for name in os.listdir(HOME):
        p = os.path.join(HOME, name)
        shutil.rmtree(p) if os.path.isdir(p) else os.remove(p)
